import { getLocalizedText } from "../../assets";
import { Router } from "../routes";
import { IGameOverSceneData } from "../interfaces";
import { Dialogs } from "../../ui";
import { globalEvents } from "../../globalEvents";

interface IProps {
  scene: Phaser.Scene;
  gameOverData: IGameOverSceneData;
}

export class GameOverView {
  constructor(private props: IProps) {
    const { scene } = this.props;
    const dialogs = new Dialogs(scene);

    const { money } = this.props.gameOverData;
    const moneyStatusText = getLocalizedText("gameOver.moneyTemplate", {
      sessionLoot: money.sessionLoot,
      total: money.total,
    });

    const goLevelMapScreen = () => {
      new Router(scene).goLevelMapFromGameOver();
    };

    if (this.props.gameOverData.isPlayerWin) {
      const message = getLocalizedText("gameOver.win") + "\n" + moneyStatusText;
      dialogs.gameWin({
        message,
        onOkClick: () => {
          goLevelMapScreen();
        },
      });
    } else {
      const message = getLocalizedText("gameOver.fail") + "\n" + moneyStatusText;
      dialogs.gameFailed({
        message,
        onOkClick: () => {
          globalEvents.emit('showAdsFullScreenTry');
          new Router(scene).showFullAdFromGameOver();
        },
      });
    }
  }
}
