import { SimpleCell } from "./SimpleCell";
import { MineCellImageBuilder, IMineSweeperFieldState } from "./interfaces";
import {
  IMineSweeperLevel,
  IMineSweeperLevelCell,
  IMinesweeperLevelCellPlace,
} from "./logic/customMineField/interfaces";
import { flatArray2D, forEach2D, map2D } from "../../common";
import { MineSweeperFieldManipulator } from "./logic/customMineField/MineSweeperFieldManipulator";

interface IProps {
  scene: Phaser.Scene;
  level: IMineSweeperLevel;
  cellSize: number;
  hardLevelMultiplier: number;
  onCellDown?: (cellView: SimpleCell) => void;
  // при вскрытии каждой ячейки - применять осторожно, возможно вообще не применять
  onCellReveal?: (cellView: SimpleCell) => void;
  // пакетный метод для обработки успешно вскрытых ячеек
  onCellArrayRevealed?: (cellViews: SimpleCell[]) => void;
  onCellFlagged?: (cellView: SimpleCell) => void;
  onGameOver?: (isWin: boolean) => void;
  imageBuilder: MineCellImageBuilder;
}

export class CustomFieldMinesweeper extends Phaser.GameObjects.Container {
  private readonly grid: (SimpleCell | undefined)[][];
  /** копия логических ячеек для быстрого перебора **/
  private readonly cellPlaces: IMinesweeperLevelCellPlace[][];
  private readonly fieldState: IMineSweeperFieldState = {
    time: 0,
    openedCells: 0,
    flaggedMines: 0,
    incorrectFlags: 0,
    multiplier: 1,
    isGameStarted: false,
    isGameOver: false,
    startTime: 0,
    totalMines: 0,
  };
  private readonly fieldManipulator: MineSweeperFieldManipulator;

  constructor(private props: IProps) {
    super(props.scene);
    const { scene, level, hardLevelMultiplier } = props;

    this.fieldState.multiplier = hardLevelMultiplier;
    this.fieldState.totalMines = level.minesAmount;
    this.fieldManipulator = new MineSweeperFieldManipulator();

    // создаем ячейки и мины по уровню,
    // в уровне мины и маркеры расставлены
    this.cellPlaces = JSON.parse(JSON.stringify(level.cellPlaces));
    this.grid = this.createCellViews(this.cellPlaces);

    // добавлям ячейки к контейнеру
    forEach2D(this.grid, (cell) => {
      if (cell) this.add(cell);
    });
    scene.add.existing(this);
  }

  private createCellViews(cellPlaces: IMinesweeperLevelCellPlace[][]) {
    const { scene, cellSize, onCellDown, imageBuilder } = this.props;

    return map2D(cellPlaces, (cell) => {
      if (cell == null) return; // пустая клетка, не создаем

      return new SimpleCell({
        scene,
        cell,
        cellSize,
        onCellDown: (cellView) => {
          onCellDown?.(cellView);
        },
        onClick: (cellView) => this.handleCellClick(cellView),
        onRightClick: (cellView) => this.handleCellRightClick(cellView),
        imageBuilder,
      });
    });
  }

  private mapCells2Views(cells: IMineSweeperLevelCell[]): SimpleCell[] {
    return cells.map((cell) => this.grid[cell.column][cell.row]).filter((s) => s != null) as SimpleCell[];
  }

  private handleCellClick(cellView: SimpleCell) {
    if (this.fieldState.isGameOver) return;
    const cell = cellView.cell;

    const { fieldState: state } = this;
    const { onCellArrayRevealed } = this.props;
    if (cell.isRevealed || cell.isFlagged) return;

    /** Начало игры - первый клик **/
    const isFirstClick = !state.isGameStarted;
    if (isFirstClick) {
      this.ensureFirstClick(cell);
      state.startTime = Date.now();
      state.isGameStarted = true;
    }

    state.openedCells++;

    if (cell.isMine) {
      this.revealCell(cellView);
      this.gameOver(false);
    } else {
      // вскрываем ячейки
      const cellsToReveal = this.fieldManipulator.findCellsToReveal(cell, this.cellPlaces);
      const cellsViewsToReveal = this.mapCells2Views(cellsToReveal);
      cellsViewsToReveal.forEach((cellView) => {
        this.revealCell(cellView);
      });
      onCellArrayRevealed?.(cellsViewsToReveal);
    }

    if (this.checkWinCondition()) {
      this.gameOver(true);
    }
  }

  /** Проверяем cellPlaces - что все ячейки вскрыты и ни на одной не мины **/
  private checkWinCondition() {
    const cells = flatArray2D(this.grid);
    const noMines = cells.filter((cell) => cell != null && !cell.cell.isMine) as SimpleCell[];
    return noMines.every((cell) => cell.cell.isRevealed);
  }

  private revealCell(cellView: SimpleCell) {
    cellView.cell.isRevealed = true;
    cellView.reveal();
    this.props.onCellReveal?.(cellView);
  }

  private ensureFirstClick(cell: IMineSweeperLevelCell) {
    if (!cell.isMine) return;
    this.fieldManipulator.moveMineFromCell(cell, this.cellPlaces);
    this.fieldManipulator.calculateAdjacentMines(this.cellPlaces);
  }

  private gameOver(isWin: boolean) {
    const { onGameOver } = this.props;
    this.fieldState.isGameOver = true;
    if (!isWin) {
      setTimeout(() => {
        this.revealAllMines();
        onGameOver?.(false);
      }, 350);
    } else {
      onGameOver?.(true);
    }
  }

  private revealAllMines() {
    forEach2D(this.grid, (cellView) => {
      if (cellView == null) return;
      if (cellView.cell.isMine) {
        this.revealCell(cellView);
      }
    });
  }

  private handleCellRightClick(cellView: SimpleCell) {
    if (this.fieldState.isGameOver) return;

    const { cell } = cellView;
    if (cell.isRevealed || this.fieldState.isGameOver) return;

    if (!this.fieldState.isGameStarted) {
      this.fieldState.isGameStarted = true;
      this.fieldState.startTime = Date.now();
    }

    cellView.toggleFlag();

    if (cell.isFlagged) {
      if (cell.isMine) {
        this.fieldState.flaggedMines++;
      } else {
        this.fieldState.incorrectFlags++;
      }
    } else {
      if (cell.isMine) {
        this.fieldState.flaggedMines--;
      } else {
        this.fieldState.incorrectFlags--;
      }
    }

    this.props.onCellFlagged?.(cellView);
  }

  public updateStateTime() {
    if (this.fieldState.isGameStarted) {
      this.fieldState.time = Math.floor((Date.now() - this.fieldState.startTime) / 1000);
    }
  }

  public getFieldState = () => {
    return { ...this.fieldState };
  };
}
