import { forEach2D, getNears } from "../../../../common";
import { IMineSweeperCellLoot, IMineSweeperLevelCell, IMinesweeperLevelCellPlace } from "./interfaces";

export class MineSweeperFieldManipulator {
  constructor() {}

  /**
   * Размещает мины на поле
   * меняет  cellPlaces
   **/
  placeRandomMines(minesAmount: number, cellPlaces: IMinesweeperLevelCellPlace[][]) {
    const freeCells = this.getFreeCells(cellPlaces);

    if (freeCells.length === 0) {
      console.warn("No freecells found.");
      return;
    }

    if (minesAmount >= freeCells.length) {
      console.warn("Warning: All cells are filled with mines!");
      minesAmount = freeCells.length - 1;
    }

    // перемешиваем свободные ячейки
    shuffleFlatArray(freeCells);

    for (let i = 0; i < minesAmount; i++) {
      const freeCell = freeCells.pop();
      /** Предполагается, что мест хватит, но если не хватило - все **/
      if (freeCell == null) {
        console.warn("No freecells found.");
        return;
      }

      /**
       *  Нормальный сценарий - ставим мину
       *  и она уже выбрана из массива, так что идем дальше
       **/
      freeCell.isMine = true;
    }

    return;
  }

  /**
   * Размещает лут на поле
   * меняет  cellPlaces
   **/
  placeRandomLoot({ cellPlaces, loots }: { cellPlaces: IMinesweeperLevelCellPlace[][], loots: IMineSweeperCellLoot[] }) {
    const freeCells = this.getFreeCells(cellPlaces);

    /** проверка на допустимость размещения лута **/
    if (freeCells.length === 0) return;

    // перемешиваем свободные ячейки
    shuffleFlatArray(freeCells);

    /** размещать  надо только на том, что есть **/
    const max = Math.min(freeCells.length, loots.length);
    for (let i = 0; i < max; i++) {
      const freeCell = freeCells.pop();
      /** Предполагается, что мест хватит, но если не хватило - все **/
      if (freeCell == null) {
        console.warn("No freecells found.");
        return;
      }

      const nextLoot = loots[i];
      freeCell.loot = {
        ...nextLoot,
      }
    }

    return;
  }

  /** Обновить состояние мин **/
  calculateAdjacentMines(cellPlaces: IMinesweeperLevelCellPlace[][]): void {
    forEach2D(cellPlaces, (cell, col, row) => {
      if (cell == null || cell.isMine) return;
      let minesCount = 0;
      const nears = getNears(cellPlaces, col, row, 1);
      nears.forEach((near) => {
        if (near?.isMine) minesCount++;
      });
      cell.adjacentMines = minesCount;
    });
  }

  /** Свободные ячейки
   * - без мин
   * - без флага
   * - без открытия
   * - без лута
    **/
  getFreeCells(cellPlaces: IMinesweeperLevelCellPlace[][]): IMineSweeperLevelCell[] {
    const freecells: IMineSweeperLevelCell[] = [];
    forEach2D(cellPlaces, (cell) => {
      if (cell == null) return;
      if (cell.isMine) return;
      if (cell.isFlagged) return;
      if (cell.isRevealed) return;
      if (cell.loot != null) return;

      freecells.push(cell);
    });
    return freecells;
  }

  getRandomFreeArray(cellPlaces: IMinesweeperLevelCellPlace[][]): IMineSweeperLevelCell[] {
    return shuffleFlatArray(this.getFreeCells(cellPlaces));
  }

  /** Переместить мину на первый соседний участок **/
  moveMineFromCell(fromCell: IMineSweeperLevelCell, cells2D: IMinesweeperLevelCellPlace[][]) {
    if (!fromCell.isMine) return;
    const freeCells = this.getFreeCells(cells2D);
    /** проверка что есть куда **/
    if (freeCells.length === 0) {
      console.warn("Warning: Cannot move mine, all cells are occupied!");
      return;
    }

    /** Просто помечаем новую ячейку как мину **/
    const randomIndex = Phaser.Math.Between(0, freeCells.length - 1);
    const newMineCell = freeCells[randomIndex];
    newMineCell.isMine = true;
    /** а себя освобождаем **/
    fromCell.isMine = false;
  }

  /** подсчитывает массив ячеек которые надо открыть **/
  findCellsToReveal(
    startCell: IMineSweeperLevelCell,
    cellplaces: IMinesweeperLevelCellPlace[][],
  ): IMineSweeperLevelCell[] {
    /** очередь для поиска соседей **/
    const queue: IMineSweeperLevelCell[] = [startCell];
    const processed = new Set<string>();
    const cellsToReveal = new Set<IMineSweeperLevelCell>();
    cellsToReveal.add(startCell);

    if (startCell.adjacentMines > 0) {
      return Array.from(cellsToReveal);
    }

    while (queue.length > 0) {
      const currentCell = queue.shift();
      if (currentCell === undefined) {
        console.log("-------- currentCell === undefined");
        continue;
      }

      const key = `${currentCell.column}_${currentCell.row}`;
      if (processed.has(key)) continue;
      processed.add(key);

      // собираем все ячейки, которые не вскрыты, не флаги и с нулем соседей мин
      const neighbors = getNears(cellplaces, currentCell.column, currentCell.row);

      neighbors.forEach((neighbor) => {
        if (neighbor == null) return;
        if (!neighbor.isRevealed && !neighbor.isFlagged) {
          cellsToReveal.add(neighbor);

          if (neighbor.adjacentMines === 0) {
            queue.push(neighbor);
          }
        }
      });
    }

    return Array.from(cellsToReveal);
  }
}

function shuffleFlatArray<T>(arr: T[]) {
  arr.sort(() => Math.random() - 0.5);
  return arr;
}
