interface INumberFormat {
  threshold: number;
  suffix: string;
}

const NUMBER_FORMATS: INumberFormat[] = [
  { threshold: 1e24, suffix: "Sp" },
  { threshold: 1e21, suffix: "Sx" },
  { threshold: 1e18, suffix: "Qi" },
  { threshold: 1e15, suffix: "Qa" },
  { threshold: 1e12, suffix: "T" },
  { threshold: 1e9, suffix: "B" },
  { threshold: 1e6, suffix: "M" },
  { threshold: 1e3, suffix: "K" },
];

const DECIMAL_PLACES = 2;

interface IProps {
  num: number;
  maxNumbers?: number;
  numberFormats?: INumberFormat[];
  disableSpaceAfterDigits?: boolean;
}

/** Форматирует число в idle/clicker стиле с суффиксами K, M, B, T */
export function getNumberStringIdleFormat({ num, maxNumbers, numberFormats = NUMBER_FORMATS, disableSpaceAfterDigits = false }: IProps): string {
  const digitCount = num.toString().length;

  if (maxNumbers !== undefined && digitCount <= maxNumbers) {
    return num.toString();
  }

  if (num < 1000) {
    return num.toString();
  }

  const afterDigits: string = disableSpaceAfterDigits ? '' : ' ';

  for (const format of numberFormats) {
    if (num >= format.threshold) {
      const value = num / format.threshold;
      const rounded = Math.floor(value * Math.pow(10, DECIMAL_PLACES)) / Math.pow(10, DECIMAL_PLACES);
      return `${rounded}${afterDigits}${format.suffix}`;
    }
  }

  return num.toString();
}
