import { ASSETS } from "../../assets";
import { gameObjectButton } from "../../components/ui";
import { Align } from "@kvisaz/phaser-sugar";
import { Router, Scenes } from "../../scenes/routes";
import { Dialogs } from "../Dialogs";
import { SceneEvents, SoundEffect } from "../../SceneEvents";

interface IProps {
  scene: Phaser.Scene;
  route: Scenes;
  isAutoScenePlace: boolean;
  exitDialog?: {
    title: string;
    text: string;
  };
}

export function uiIconBackButton({ scene, isAutoScenePlace, route, exitDialog }: IProps) {
  const builder = ASSETS.images.builder(scene);

  const gameObject = builder.build.button_back();

  if (isAutoScenePlace) {
    const align = new Align();
    align.anchorSceneScreen(scene).leftIn(gameObject, 20).topIn(gameObject, 20);
    scene.add.existing(gameObject);
  }

  const onClick = () => {
    const goBack = () => new Router(scene).go(route);
    const dialogs = new Dialogs(scene);
    if (exitDialog) {
      dialogs.backButton({
        title: exitDialog.title,
        text: exitDialog.text,
        onOkClick: () => {
          goBack();
        },
        onCancelClick: () => {},
      });
    } else {
      goBack();
    }
  };

  const sceneEvents = new SceneEvents(scene);

  return gameObjectButton({
    gameObject,
    inputTracker: gameObject,
    onClick: () => {
      sceneEvents.emit('soundEffect', SoundEffect.click);
      onClick();
    },
    onOver: () => {
      sceneEvents.emit('soundEffect', SoundEffect.buttonHover);
    },
    options: {
      once: false,
      overMoveY: 4,
      clickMode: "up",
    },
  }) as Phaser.GameObjects.Image;
}
