import { ASSETS } from "../../assets";
import { MainAtlas } from "../../assets/atlases";
import { Align, cssColorToInt } from "@kvisaz/phaser-sugar";
import { fitToSize } from "../../common";
import { getNumberStringIdleFormat } from "../../common/string/getNumberStringIdleFormat";

export type LevelButtonType = "completed" | "current" | "buyable" | "locked" | "not_enough_money";

export interface ILevelButtonProps {
  scene: Phaser.Scene;
  type: LevelButtonType;
  levelNumber: number;
  levelPrice: number;
  size?: number;
}

export const makeLevelButton = ({ scene, levelPrice, type, levelNumber, size = 128 }: ILevelButtonProps) => {
  const assetBuilder = ASSETS.images.builder(scene);

  const levelPriceString = getNumberStringIdleFormat({ num: levelPrice, maxNumbers: 4 });

  if (type === "completed") {
    return new CompletedLevelButton({
      scene,
      assetBuilder,
      levelNumber,
      size,
    });
  }

  if (type === "current") {
    return new CurrentLevelButton({
      scene,
      assetBuilder,
      levelNumber,
      size,
    });
  }

  if (type === "buyable") {
    return new BuyableLevelButton({
      scene,
      assetBuilder,
      levelNumber,
      levelPriceString,
      size,
    });
  }

  if (type === "not_enough_money") {
    return new NotEnoughMoneyLevelButton({
      scene,
      assetBuilder,
      levelNumber,
      levelPriceString,
      size,
    });
  }

  return new LockedLevelButton({
    scene,
    assetBuilder,
    levelNumber,
    levelPriceString,
    size,
  });
};

interface ICompletedPriceButtonProps {
  scene: Phaser.Scene;
  assetBuilder: MainAtlas;
  parentSize?: number;
}

class CompletedPriceButton extends Phaser.GameObjects.Container {
  constructor({ scene, assetBuilder, parentSize = 128 }: ICompletedPriceButtonProps) {
    super(scene);

    const scale = parentSize / 128;
    const bg = assetBuilder.build.buy_button_bg_nineslice(108 * scale, 32 * scale);
    bg.width = bg.width * 0.8;
    bg.setTint(cssColorToInt("#88fb88"));

    const checkIcon = assetBuilder.build.icon_mark_green();
    fitToSize({
      gameObject: checkIcon,
      width: 30 * scale,
      height: 23 * scale,
    });
    new Align(bg).center(checkIcon);
    this.add([bg, checkIcon]);
  }
}

interface IBuyablePriceButtonProps {
  scene: Phaser.Scene;
  assetBuilder: MainAtlas;
  levelPriceString: string;
  parentSize?: number;
}

class BuyablePriceButton extends Phaser.GameObjects.Container {
  constructor({ scene, assetBuilder, levelPriceString, parentSize = 128 }: IBuyablePriceButtonProps) {
    super(scene);

    const scale = parentSize / 128;
    const bg = assetBuilder.build.buy_button_bg_nineslice(108 * scale, 32 * scale);
    const align = new Align();

    const coin = assetBuilder.build.icon_money_128();
    fitToSize({
      gameObject: coin,
      width: 32 * scale,
      height: 32 * scale,
    });
    align.anchor(bg).leftIn(coin, 1).centerY(coin);

    const numberView = new PriceButtonText({
      scene,
      text: levelPriceString,
    });

    align.anchor(bg).center(numberView, coin.getBounds().width * 0.4, 0);
    this.add([bg, coin, numberView]);
  }
}

