interface ICompletedLevelButtonProps {
  scene: Phaser.Scene;
  assetBuilder: MainAtlas;
  levelNumber: number;
  size: number;
}

class CompletedLevelButton extends Phaser.GameObjects.Container {
  public inputTracker: Phaser.GameObjects.NineSlice;

  constructor({ scene, assetBuilder, levelNumber, size }: ICompletedLevelButtonProps) {
    super(scene);

    const bg = assetBuilder.build.island_level_nineslice(size, size);
    this.inputTracker = bg;

    const textMaxWidth = bg.getBounds().width * 0.9;

    const numberView = new LevelNumber({
      scene,
      text: `${levelNumber}`,
      textMaxWidth,
    });

    const priceButton = new CompletedPriceButton({
      scene,
      assetBuilder,
      parentSize: size,
    });

    const align = new Align();
    align.anchor(bg).centerX(numberView).topIn(numberView, 20);
    align.anchor(bg).centerX(priceButton).bottomIn(priceButton, -11);

    this.add([bg, numberView, priceButton]);
  }
}

interface ICurrentLevelButtonProps {
  scene: Phaser.Scene;
  assetBuilder: MainAtlas;
  levelNumber: number;
  size: number;
}

class CurrentLevelButton extends Phaser.GameObjects.Container {
  public inputTracker: Phaser.GameObjects.NineSlice | Phaser.GameObjects.Image;

  constructor({ scene, assetBuilder, levelNumber, size }: ICurrentLevelButtonProps) {
    super(scene);

    const bg = assetBuilder.build.island_level_nineslice_current(size, size);
    fitToSize({
      gameObject: bg,
      width: size,
      height: size,
    });
    this.inputTracker = bg;

    const textMaxWidth = bg.getBounds().width * 0.9;

    const numberView = new LevelNumber({
      scene,
      text: `${levelNumber}`,
      textMaxWidth,
      color: "#ffffff",
      strokeThickness: 4,
      stroke: '#06579F',
      fontSize: "62px",
    });

    const align = new Align();
    align.anchor(bg).center(numberView);
    this.add([bg, numberView]);
  }
}

