interface ILockedLevelButtonProps {
  scene: Phaser.Scene;
  assetBuilder: MainAtlas;
  levelNumber: number;
  levelPriceString: string;
  size: number;
}

class LockedLevelButton extends Phaser.GameObjects.Container {
  public inputTracker: Phaser.GameObjects.NineSlice;

  constructor({ scene, assetBuilder, levelNumber, levelPriceString, size }: ILockedLevelButtonProps) {
    super(scene);

    const bg = assetBuilder.build.island_level_nineslice(size, size);
    this.inputTracker = bg;

    const textMaxWidth = bg.getBounds().width * 0.9;

    const numberView = new LevelNumber({
      scene,
      text: `${levelNumber}`,
      textMaxWidth,
    });

    const priceButton = new LockedPriceButton({
      scene,
      assetBuilder,
      priceText: levelPriceString,
      parentSize: size,
    });

    const lockIcon = assetBuilder.build.icon_lock();
    lockIcon.setScale(0.5);
    const lockIconBounds = lockIcon.getBounds();

    const align = new Align();
    align.anchor(bg).centerX(numberView).topIn(numberView, 20);
    align.anchor(bg).centerX(priceButton).bottomIn(priceButton, -11);
    align.anchor(bg).rightIn(lockIcon, lockIconBounds.width/4).bottomIn(lockIcon, lockIconBounds.height/8);

    this.add([bg, numberView, priceButton, lockIcon]);
  }
}

interface IPriceButtonTextProps extends Phaser.Types.GameObjects.Text.TextStyle {
  scene: Phaser.Scene;
  text: string;
  parentSize?: number;
}

class PriceButtonText extends Phaser.GameObjects.Text {
  constructor({ scene, text, parentSize = 128, ...textStyle }: IPriceButtonTextProps) {
    const scale = parentSize / 128;
    super(scene, 0, 0, text, {
      fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
      fontSize: `${Math.round(20 * scale)}px`,
      color: "#ffffff",
      stroke: "#08518E",
      strokeThickness: 2,
      align: "center",
      ...textStyle,
    });
  }
}

interface ILevelNumberProps extends Phaser.Types.GameObjects.Text.TextStyle {
  scene: Phaser.Scene;
  text: string;
  textMaxWidth: number;
}

class LevelNumber extends Phaser.GameObjects.Text {
  constructor({ scene, text, textMaxWidth, ...textStyle }: ILevelNumberProps) {
    super(scene, 0, 0, text, {
      fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
      fontSize: "54px",
      color: "#505050",
      align: "center",
      wordWrap: {
        width: textMaxWidth,
      },
      ...textStyle,
    });
  }
}
