import { IGameState, ILogic, IView, IViewSignals } from "./interfaces";

interface IProps {
  minesAmount: number;
  playerGold: number;
  winBonusCoins: number;
}

export class GameLogic implements ILogic {
  private view!: IView;

  gameState: IGameState;
  private readonly minesAmount: number;

  constructor({ minesAmount, playerGold, winBonusCoins }: IProps) {
    this.minesAmount = minesAmount;
    this.gameState = {
      winBonusCoins,
      mines: { hidden: minesAmount },
      money: {
        total: playerGold,
        sessionLoot: 0,
      },
    };
  }

  init(view: IView) {
    this.view = view;
    this.view.onLogicCommand("initGame", {
      money: {
        total: this.gameState.money.total,
        sessionLoot: this.gameState.money.sessionLoot,
      },
      minesHidden: this.gameState.mines.hidden,
    });
  }

  onViewSignal<T extends keyof IViewSignals>(signal: T, data: IViewSignals[T]): void {
    switch (signal) {
      case "onCellFlagged": {
        const { flaggedMines, incorrectFlags } = data as IViewSignals["onCellFlagged"];
        const totalFlags = flaggedMines + incorrectFlags;
        this.gameState.mines.hidden = Math.max(0, this.minesAmount - totalFlags);
        this.view.onLogicCommand("mineUpdate", { minesHidden: this.gameState.mines.hidden });
        break;
      }
      case "onCoinFinished": {
        const { coinValue } = data as IViewSignals["onCoinFinished"];
        this.gameState.money.sessionLoot += coinValue;
        this.gameState.money.total += coinValue;
        this.view.onLogicCommand("moneyUpdate", { money: this.gameState.money.total });
        break;
      }
      case "onAllCoinFinished": {
        // все монетки обновились - сохраняемся
        this.view.onLogicCommand("savePlayerGold", this.gameState.money.total);
        break;
      }
      case "onCellArrayRevealed": {
        break;
      }
      case "onFieldGameOver": {
        const { isPlayerWin } = data as IViewSignals["onFieldGameOver"];
        const winBonusCoins = isPlayerWin ? this.gameState.winBonusCoins : 0;
        this.view.onLogicCommand("showGameOverAnimation", { isPlayerWin, winBonusCoins });
        break;
      }
      case "onGameOverAnimationFinish": {
        const { isPlayerWin } = data as IViewSignals["onGameOverAnimationFinish"];
        const { money } = this.gameState;
        this.view.onLogicCommand("showGameOverScreen", { isPlayerWin, money });
        break;
      }
      case "restartButtonClick": {
        break;
      }
      case "onGameStateLoaded": {
        const saveData = data as IViewSignals["onGameStateLoaded"];
        this.gameState.money.total = saveData?.moneyTotal ?? this.gameState.money.total;
        break;
      }
      default:
        console.warn("unknown view signal: ", signal);
    }
  }
}
