import { ILevel } from "../../interfaces";
import { IMineSweeperCellLoot } from "../../../components/Minesweeper/logic/customMineField/interfaces";

interface IProps {
  /**
   * общее число уровней
   * оно должно рассчитываться вместе с формулами дохода
   * так чтобы последние уровни были достижимы за время существования вселенной
   **/
  levelsAmount: number;

  /** формула для дохода уровня **/
  levelIncome(level: number): number;

  /** формула для стоимости следующего уровня после level **/
  levelNextCost(level: number): number;

  /** количество мин на текущем уровне  **/
  levelMineAmount(args: { columns: number; rows: number; level: number }): number;

  /** доля свободных монет от текущего сокровища, меньше 1, больше 0  **/
  freeCoinsPartOfIncome: number;

  /** образцы уровней  для сэмлирования **/
  levelsSamples: {
    first: {
      columns: number;
      rows: number;
      roundX: number;
      roundY: number;
    };
    last: {
      columns: number;
      rows: number;
      roundX: number;
      roundY: number;
    };
  };
}

export function generateLevels({
  levelMineAmount,
  levelsAmount,
  levelNextCost,
  freeCoinsPartOfIncome,
  levelIncome,
  levelsSamples,
}: IProps): ILevel[] {
  if (levelsAmount < 0) {
    throw new Error("levelsAmount must be a non-negative integer.");
  }

  const levels: ILevel[] = new Array(levelsAmount);

  const lerp = (a: number, b: number, t: number) => a + t * (b - a);
  const { first, last } = levelsSamples;

  for (let levelNumber = 0; levelNumber < levelsAmount; levelNumber++) {
    const levelPercent = levelNumber / (levelsAmount - 1);

    const columns = Math.round(lerp(first.columns, last.columns, levelPercent));
    const rows = Math.round(lerp(first.rows, last.rows, levelPercent));
    const minesAmount = levelMineAmount({ level: levelNumber, columns, rows });

    const loots: IMineSweeperCellLoot[] = [];

    /**
     * свободные монетки, как и мины, рассчитываются пока по итерационной формуле
     * остаток необходимый для дополнения до totalCoins - выдается при победе
     * **/
    const totalCoins = levelIncome(levelNumber);
    const freeCells = columns * rows - minesAmount;
    /** в свободные ячейки уходит часть общего количества монеток,
     *  основное выдается из сундука
     * **/
    const maxFreeCoins = Math.floor(freeCells * 0.7);
    /** свободные ячейки проверяем на допустимость **/
    freeCoinsPartOfIncome = limitPart(freeCoinsPartOfIncome, 0.1, 0.9);
    const partFreeCoins = Math.round(freeCoinsPartOfIncome * totalCoins);
    const freeCoins = Math.min(maxFreeCoins, partFreeCoins);
    /** остаток для сундука **/
    const winBonusCoins = totalCoins - freeCoins;

    /** 1 монетка == 1 золотой в валюте **/
    for (let i = 0; i < freeCoins; i++) {
      loots.push({
        type: "coins",
        value: 1,
      });
    }

    levels[levelNumber] = {
      id: levelNumber,
      columns,
      rows,
      levelNextCost: levelNextCost(levelNumber),
      winBonusCoins,
      loots,
      minesAmount,

      roundX: Math.round(lerp(first.roundX, last.roundX, levelPercent)),
      roundY: Math.round(lerp(first.roundY, last.roundY, levelPercent)),
    };
  }

  return levels;
}

function limitPart(part: number, min: number, max: number) {
  if (part < min) {
    console.warn("part < min");
    return min;
  }
  if (part > max) {
  }
  return part;
}
