import { Router, Scenes } from "../routes";
import { SceneBg, SoundManager } from "../../ui";
import { ASSETS } from "../../assets";
import { Align } from "@kvisaz/phaser-sugar";
import { fitToSize } from "../../common";
import { Animator } from "../../games/MineSweeper/utils";
import { globalEvents } from "../../globalEvents";
import { services } from "../../serviceProvider";

export class AdFullScreenScene extends Phaser.Scene {
  constructor() {
    super(Scenes.AdFullScreen);
  }


  create() {
    const scene = this;
    const assetsBuilder = ASSETS.images.builder(scene);
    const align = new Align();
    const { soundMusicSettings } = services;
    const soundManager = new SoundManager({ scene, soundMusicSettings});

    soundManager.onAdFullStart();

    new SceneBg({ scene: this });


    /** center - ship  **/
    const shipIcon = assetsBuilder.build.ship_2_macht();
    fitToSize({
      gameObject: shipIcon,
      width: 125,
      height: 125,
    });
    shipIcon.flipX = true;
    shipIcon.setOrigin(0.5, 1);
    scene.add.existing(shipIcon);

    align.anchorSceneScreen(scene).center(shipIcon);

    /** shipIcon animation **/
    Animator.addShipIdleAnimation(shipIcon);

    /** уйти когда сервис рекламы передас сообщение **/
    globalEvents.once('showAdsFullScreenFinish', ()=> {
      soundManager.onAdFullFinish();
      new Router(scene).goLevelMapFromFullAd();
    });
  }
}
