import { Align } from "@kvisaz/phaser-sugar";
import { getLocalizedText, ASSETS } from "../../assets";
import { SceneBg, uiIconSettingsButton, uiTextButton } from "../../ui";
import { Router, Scenes } from "../routes";

interface IProps {
  scene: Phaser.Scene;
}

export class StartView {
  constructor(private props: IProps) {
    const { scene } = this.props;
    const align = new Align();

    new SceneBg({ scene });

    const titleText = getLocalizedText("start.logo.title");
    const subTitleText = getLocalizedText("start.logo.subtitle");
    const buttonText = getLocalizedText("start.start");

    const title = scene.add.text(0, 0, titleText, {
      fontSize: 96,
      fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
      color: "#ff4603",
      stroke: "#ffeec5",
      strokeThickness: 12,
    });

    const subTitle = scene.add.text(0, 0, subTitleText, {
      fontSize: 48,
      fontFamily: ASSETS.font.fonts.RobotoSemiBold.fontFamily,
      color: "#23394c",
      stroke: "rgba(241,253,249,0.58)",
      strokeThickness: 12,
    });

    const imageBuilder = ASSETS.images.builder(scene);
    const mine = imageBuilder.build.icon_mine();
    mine.setScale(0.65);
    scene.add.existing(mine);

    const button = uiTextButton({
      scene,
      text: buttonText.toUpperCase(),
      type: "accent",
      onClick: () => new Router(scene).go(Scenes.LevelMap),
    });
    scene.add.existing(button);

    /** settings button **/
    const uiSettingsButton = uiIconSettingsButton({ scene });
    scene.add.existing(uiSettingsButton);
    align.anchorSceneScreen(scene).rightIn(uiSettingsButton, -20).topIn(uiSettingsButton, 20);

    align.setPosition(title, 550, 215);
    align.anchor(title).leftIn(subTitle).bottomTo(subTitle, -12);
    align.anchor(subTitle).rightTo(mine).centerY(mine, 3);
    align.anchor(subTitle).leftIn(button, 12).bottomTo(button, 12);


    // testing
    // new Router(scene).go(Scenes.LevelMap);
  }
}
