import {
  IMineSweeperCellLoot,
  IMineSweeperLevel,
  IMineSweeperLevelCell,
  IMinesweeperLevelCellPlace
} from "./interfaces";
import { makeArray2D, roundCorners } from "../../../../common";
import { MineSweeperFieldManipulator } from "./MineSweeperFieldManipulator";

/** интерфейс для генерации уровня **/
interface IMinesweeperLevelSeedArgs {
  columns: number;
  rows: number;
  minesAmount: number;
  loots?: IMineSweeperCellLoot[];
}

interface IRoundCornerArgs extends IMinesweeperLevelSeedArgs {
  // учитывая квадратность - лучше задавать кратные 2 числа
  roundX?: number;
  roundY?: number;
}


const defaultNonVoidCell: IMineSweeperLevelCell = {
  isMine: false,
  isFlagged: false,
  isRevealed: false,
  adjacentMines: 0,
  column: -1,
  row: -1,
};

export class MineSweeperLevelFabric {
  private manipulator = new MineSweeperFieldManipulator();

  createRectangle({ columns, rows, minesAmount, loots=[] }: IMinesweeperLevelSeedArgs): IMineSweeperLevel {
    const cellPlaces: IMinesweeperLevelCellPlace[][] = makeArray2D<IMinesweeperLevelCellPlace>(
      columns,
      rows,
      (column, row) => {
        return {
          ...defaultNonVoidCell,
          column,
          row,
        };
      },
    );

    this.manipulator.placeRandomMines(minesAmount, cellPlaces);
    this.manipulator.placeRandomLoot({ loots, cellPlaces });
    this.manipulator.calculateAdjacentMines(cellPlaces);

    return {
      columns,
      rows,
      minesAmount,
      cellPlaces,
    };
  }

  createRoundedRectangle({ columns, rows, minesAmount, roundX, roundY, loots=[] }: IRoundCornerArgs): IMineSweeperLevel {
    const cellPlaces: IMinesweeperLevelCellPlace[][] = makeArray2D<IMinesweeperLevelCellPlace>(
      columns,
      rows,
      (column, row) => {
        return {
          ...defaultNonVoidCell,
          column,
          row,
        };
      },
    );

    const cellPlacesRounded = roundCorners({
      places: cellPlaces,
      columns,
      rows,
      roundX,
      roundY,
    }) as IMinesweeperLevelCellPlace[][];

    this.manipulator.placeRandomMines(minesAmount, cellPlacesRounded);
    this.manipulator.placeRandomLoot({ loots, cellPlaces: cellPlacesRounded });
    this.manipulator.calculateAdjacentMines(cellPlacesRounded);

    return {
      columns,
      rows,
      minesAmount,
      cellPlaces: cellPlacesRounded,
    };
  }

}
