import { IGameOverSceneData, IGameSceneData } from "./interfaces";

export enum Scenes {
  Boot = "Boot",
  Start = "Start",
  LevelMap = "LevelMap",
  Game = "Game",
  GameOver = "GameOver",
  AdFullScreen = "AdFullScreen",
}

export class Router {
  constructor(private scene: Phaser.Scene) {}

  go(key: Scenes, data?: object) {
    this.scene.scene.start(key, data);
  }

  showGameFromLevelMap(data: IGameSceneData) {
    this.scene.scene.start(Scenes.Game, data);
  }

  showGameOver(data: IGameOverSceneData) {
    this.scene.scene.pause();
    this.scene.scene.launch(Scenes.GameOver, data);
  }

  goLevelMapFromGameOver() {
    this.scene.scene.stop(Scenes.GameOver);
    this.scene.scene.stop(Scenes.Game);
    this.scene.scene.start(Scenes.LevelMap);
  }

  showFullAdFromGameOver(){
    this.scene.scene.stop(Scenes.GameOver);
    this.scene.scene.stop(Scenes.Game);
    this.scene.scene.start(Scenes.AdFullScreen);
  }

  goLevelMapFromFullAd() {
    this.scene.scene.stop();
    this.scene.scene.start(Scenes.LevelMap);
  }
}
