import { Align } from "@kvisaz/phaser-sugar";
import { ASSETS } from "../../assets";
import { fitToSize, numberToString } from "../../common";

interface IProps {
  scene: Phaser.Scene;
  value?: number;
}

export class UiMoneyCounter extends Phaser.GameObjects.Container {
  private text: Phaser.GameObjects.Text;

  constructor(private props: IProps) {
    super(props.scene);
    const { scene } = props;
    const assetBuilder = ASSETS.images.builder(scene);

    const bg = assetBuilder.build.nine_light_blue_stroked(237, 80);

    const icon = assetBuilder.build.icon_money_128();
    fitToSize({
      gameObject: icon,
      width: 95,
      height: 95,
    });

    const value = numberToString({ num: props.value ?? 0, addSpaceAfter3digits: true });
    const text = new Phaser.GameObjects.Text(scene, 0, 0, value, {
      fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
      fontSize: "50px",
      color: "#23394C",
      align: "left",
    });
    this.text = text;

    const align = new Align();
    align.anchor(bg).centerY(icon).leftIn(icon, -32);
    align.anchor(icon).centerY(text).rightTo(text, 4);

    this.add([bg, icon, text]);
  }

  setValue(value: number) {
    const text = value.toString();
    if (this.text.text === text) return;
    this.text.setText(value.toString());
  }
}
