import { loadFont } from "@kvisaz/phaser-sugar";

const urlBase = "./assets/fonts";

const fontFamilyPrimary = "Primary";
const fontFamilyBalsamiqSansBold = "PrimaryBold";
const fontFamilyRegular = "Regular";
const RalewayBlack = "RalewayBlack";

const fonts = {
  RobotoRegular: {
    fontFamily: "Roboto Regular",
    url: `${urlBase}/Roboto-Regular.woff2`,
  },
  RobotoBold: {
    fontFamily: "Roboto Bold",
    url: `${urlBase}/Roboto-Bold.woff2`,
  },
  RobotoSemiBold: {
    fontFamily: "Roboto Semi Bold",
    url: `${urlBase}/Roboto-SemiBold.woff2`,
  },
};

export const MineSweeperFonts = {
  /** просто указывает на старт загрузки **/
  load(scene: Phaser.Scene): void {
    Object.values(fonts).forEach((font) => {
      loadFont({
        scene,
        ...font,
      });
    });
  },
  fonts,
  fontFamily: {
    primary: fontFamilyPrimary,
    primaryBold: fontFamilyBalsamiqSansBold,
    regular: fontFamilyRegular,
    RalewayBlack,
    button: RalewayBlack,
    cellNumber: fontFamilyBalsamiqSansBold,
  },
};
