import { ASSETS } from "../../assets";
import { gameObjectButton } from "../../components/ui/Button/GameObjectButton";
import { Align } from "@kvisaz/phaser-sugar";
import { SceneEvents, SoundEffect } from "../../SceneEvents";

interface IProps {
  scene: Phaser.Scene;
  text: string;
  onClick: () => void;
  type?: "primary" | "accent";
  width?: number;
  height?: number;
  fontSizePx?: number;
  options?: {
    once?: boolean;
    clickMode?: "down" | "up";
    overMoveY?: number;
  };
}

export function uiTextButton({
  scene,
  onClick,
  text,
  type = "primary",
  fontSizePx = 55,
  width = 320,
  height = 80,
  options,
}: IProps) {
  options = {
    once: true,
    overMoveY: 4,
    clickMode: "up",
    ...options,
  };
  const builder = ASSETS.images.builder(scene);

  const gameObject = new Phaser.GameObjects.Container(scene);
  const bg = type === "accent" ? builder.build.button_accent(width, height) : builder.build.button_blue(width, height);

  const textObject = new Phaser.GameObjects.Text(scene, 0, 0, text, {
    fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
    fontSize: `${fontSizePx}px`,
    color: "#ffffff",
  });
  new Align(bg).center(textObject);
  gameObject.add([bg, textObject]);

  const sceneEvents = new SceneEvents(scene);
  return gameObjectButton({
    gameObject,
    inputTracker: bg,
    onClick: () => {
      sceneEvents.emit("soundEffect", SoundEffect.click);
      onClick();
    },
    onOver: () => {
      sceneEvents.emit("soundEffect", SoundEffect.buttonHover);
      },
    options,
  }) as Phaser.GameObjects.Image;
}
