import { Scenes } from "../routes";
import { LevelMapView } from "./LevelMapView";
import { levelMap } from "./config";
import { LevelMapLogic } from "./logic";
import { metaGame, services } from "../../serviceProvider";
import { SoundManager } from "../../ui";
import { SceneEvents } from "../../SceneEvents";
import { globalEvents } from "../../globalEvents";

export class LevelMapScene extends Phaser.Scene {
  constructor() {
    super(Scenes.LevelMap);
  }

  preload() {}

  create() {
    const { soundMusicSettings } = services;
    new SoundManager({ scene: this, soundMusicSettings });
    globalEvents.emit('levelSceneStart');
    this.subscribeMetaGame();
    const { levels, columns } = levelMap;

    const levelSaves = metaGame.getSavedLevels();
    const playerGold = metaGame.getPlayerGold();

    console.log("levelSaves", levelSaves);

    const logic = new LevelMapLogic({
      playerGold,
      levelSaves,
      levels,
    });

    const view = new LevelMapView({
      scene: this,
      levelDatas: logic.state.levelDatas,
      money: logic.state.moneyTotal,
      columns,
    });

    logic.init(view);
    view.init(logic);
  }

  /** метагейм слушает изменения данных во вью **/
  private subscribeMetaGame() {
    const sceneEvents = new SceneEvents(this);
    sceneEvents.on("savePlayerGold", (playerGold) => {
      metaGame.setPlayerGold(playerGold);
    });
    sceneEvents.on("unlockLevel", ({ levelId }) => {
      metaGame.unlockLevel(levelId);
    });
  }
}
