/**
 *  Глобальные эвенты для сигналов о разных состояниях игры
 */
export interface IGlobalEvents {
  bootSceneStart: undefined;
  startSceneStart: undefined;
  levelSceneStart: undefined;
  gameSceneStart: undefined;
  gameOverSceneStart: undefined;
  showAdsFullScreenTry: undefined;
  showAdsFullScreenFinish: undefined;
}

export class TypedEvents {
  constructor(private target: EventTarget) {}

  emit<T extends keyof IGlobalEvents>(eventName: T, data?: IGlobalEvents[T]) {
    this.target.dispatchEvent(new CustomEvent(eventName, { detail: data }));
  }

  on<T extends keyof IGlobalEvents>(eventName: T, callback: (data: IGlobalEvents[T]) => void, isOnce = false) {
    const wrappedCallback = ((e: Event) => {
      type EventType = IGlobalEvents[T];
      const detail = (e as CustomEvent<EventType>).detail;
      // Если у события нет данных — просто вызываем без аргументов
      if ((undefined as unknown as EventType) === undefined && detail === undefined) {
        (callback as () => void)();
      } else {
        (callback as (d: EventType) => void)(detail as EventType);
      }
    }) as EventListener;

    this.target.addEventListener(eventName, wrappedCallback, { once: isOnce });
    return () => this.target.removeEventListener(eventName, wrappedCallback);
  }

  once<T extends keyof IGlobalEvents>(eventName: T, callback: (data: IGlobalEvents[T]) => void) {
    return this.on(eventName, callback, true);
  }
}

export const globalEvents = new TypedEvents(window);


// ==== Примеры использования ====

/*

// Событие без данных — аргумент не передаём
GlobalEvents.emit('bootSceneStart');

// Подписка на событие без данных — колбэк без аргументов
const offBoot = GlobalEvents.on('bootSceneStart', () => {
  // ... ваша логика
});

// Once-подписка
GlobalEvents.once('gameOverSceneStart', () => {
  // Выполнится один раз
});

// Отписка
offBoot();
*/
