import { Align } from "@kvisaz/phaser-sugar";
import { fitToSize, getCanvasSize, scaleToSize } from "../../common";
import { ASSETS, getLocalizedText } from "../../assets";
import { Animator } from "../../games/MineSweeper/utils";
import { CustomFieldMinesweeper } from "../../components/Minesweeper/CustomFieldMinesweeper";
import { IMineSweeperLevel } from "../../components/Minesweeper/logic/customMineField/interfaces";
import { SimpleCell } from "../../components/Minesweeper/SimpleCell";
import { ILogic, ILogicInstruction, IView } from "./logic";
import { GameUi } from "./GameUi";
import { Router, Scenes } from "../routes";
import { Dialogs, InputBlocker, SceneBg } from "../../ui";
import { MainAtlas } from "../../assets/atlases";
import { gameObjectButton } from "../../components/ui";
import { MineCellImageBuilder } from "../../components/Minesweeper";
import { SceneEvents, SoundEffect } from "../../SceneEvents";
import { CoinView } from "./CoinView";

interface IProps {
  scene: Phaser.Scene;
  cellSize: number;
  gameOverEffectFailDelay: number;
  coinsFlyMaxDuration: number;
  level: IMineSweeperLevel;
  levelId: number;
}

type CellView = SimpleCell;

export class GameView implements IView {
  private logic!: ILogic;

  private isDestroyed = false;
  private minesweeper: CustomFieldMinesweeper;
  private gameUi: GameUi;
  private shipIcon: Phaser.GameObjects.Image;
  private assetsBuilder: MainAtlas;
  private islandIcon: Phaser.GameObjects.Image;
  private readonly sceneEvents: SceneEvents;

  constructor(private props: IProps) {
    const { scene, level } = this.props;
    this.sceneEvents = new SceneEvents(scene);
    this.assetsBuilder = ASSETS.images.builder(scene);
    const { width, height } = getCanvasSize(scene);
    const align = new Align();

    /** bg  **/
    new SceneBg({ scene });

    /** bg - shipIcon**/
    this.shipIcon = this.assetsBuilder.build.ship_2_macht();
    fitToSize({
      gameObject: this.shipIcon,
      width: 125,
      height: 125,
    });
    this.shipIcon.flipX = true;
    this.shipIcon.setOrigin(0.5, 1);
    scene.add.existing(this.shipIcon);
    align.anchorSceneScreen(scene).leftIn(this.shipIcon).bottomIn(this.shipIcon);

    /** title **/
    const titleText = getLocalizedText("game.title", { islandNumber: this.props.levelId + 1 });
    const title = scene.add.text(0, 0, titleText, {
      fontSize: 40,
      fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
      color: "#B6D4EF",
    });
    align.anchorSceneScreen(scene).centerX(title).topIn(title, 45);

    /** bg - shipIcon animation **/
    Animator.addShipRockAnimation(this.shipIcon);

    /** ship icon as backButton **/
    const dialogs = new Dialogs(scene);
    gameObjectButton({
      gameObject: this.shipIcon,
      inputTracker: this.shipIcon,
      options: {
        once: false,
      },
      onClick: () => {
        dialogs.backButton({
          title: getLocalizedText("backDialog.game.Title"),
          text: getLocalizedText("backDialog.Info"),
          onOkClick: () => new Router(scene).go(Scenes.LevelMap),
          onCancelClick: () => {},
        });
      },
    });

    /** footer - chest island  **/
    const islandIcon = this.assetsBuilder.build.icon_island_chest();
    scene.add.existing(islandIcon);
    align.anchorSceneScreen(scene).rightIn(islandIcon, 54).bottomIn(islandIcon, 54);
    this.islandIcon = islandIcon;

    /** minefield  **/
    const mineImageBuilder: MineCellImageBuilder = {
      cellBg: this.assetsBuilder.build.cell_revealed_sand,
      cellClosed: this.assetsBuilder.build.cell_closed_sand_01,
      flag: this.assetsBuilder.build.cell_marked,
      mine: this.assetsBuilder.build.icon_mine,
      text: (text) => {
        return new Phaser.GameObjects.Text(scene, 0, 0, text, {
          fontSize: `22px`, // will be changed kater
          color: "#EDB73E",
          fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
        });
      },
    };
    const minesweeper = new CustomFieldMinesweeper({
      scene,
      cellSize: this.props.cellSize,
      level,
      hardLevelMultiplier: 1,
      onCellArrayRevealed: this.onCellArrayRevealed.bind(this),
      onGameOver: this.onFieldGameOver.bind(this),
      onCellDown: () => {
        this.sceneEvents.emit("soundEffect", SoundEffect.click);
      },
      onCellFlagged: (cellView) => {
        const { flaggedMines, incorrectFlags } = minesweeper.getFieldState();
        this.logic.onViewSignal("onCellFlagged", { cell: cellView.cell, flaggedMines, incorrectFlags });
      },
      imageBuilder: mineImageBuilder,
    });
    scaleToSize({ gameObject: minesweeper, width: width * 0.9, height: height * 0.8 });

    this.gameUi = new GameUi({
      scene,
    });

    align.anchorSceneScreen(scene).center(minesweeper).topIn(minesweeper, 120);
    scene.add.existing(minesweeper);
    this.minesweeper = minesweeper;
  }

  destroy() {
    this.minesweeper.destroy();
  }

  init(logic: ILogic) {
    this.logic = logic;
  }

  onLogicCommand<T extends keyof ILogicInstruction>(command: T, data: ILogicInstruction[T]) {
    switch (command) {
      case "moneyUpdate": {
        const { money } = data as ILogicInstruction["moneyUpdate"];
        this.gameUi.setMoney(money);
        break;
      }
      case "mineUpdate": {
        const { minesHidden } = data as ILogicInstruction["mineUpdate"];
        this.gameUi.setMines(minesHidden);
        break;
      }
      case "initGame": {
        const { money, minesHidden } = data as ILogicInstruction["initGame"];
        this.gameUi.setMoney(money.total);
        this.gameUi.setMines(minesHidden);
        break;
      }
      case "showGameOverAnimation": {
        const { isPlayerWin, winBonusCoins } = data as ILogicInstruction["showGameOverAnimation"];
        this.showGameOverAnimation({ isPlayerWin, winBonusCoins });
        break;
      }
      case "showGameOverScreen": {
        const { isPlayerWin, money } = data as ILogicInstruction["showGameOverScreen"];
        this.sceneEvents.emit("saveLevelPlay", { isPlayerWin, levelId: this.props.levelId });
        new Router(this.props.scene).showGameOver({ isPlayerWin, money });
        break;
      }
      case "savePlayerGold": {
        const playerGold = data as ILogicInstruction["savePlayerGold"];
        this.sceneEvents.emit("savePlayerGold", playerGold);
        break;
      }
      default: {
        console.warn("unknown logic command", command, data);
      }
    }
  }

  private onFieldGameOver(isPlayerWin: boolean) {
    this.logic.onViewSignal("onFieldGameOver", { isPlayerWin });
  }

  private showGameOverAnimation({ isPlayerWin, winBonusCoins }: { isPlayerWin: boolean; winBonusCoins: number }) {
    const { scene, gameOverEffectFailDelay } = this.props;

    if (this.isDestroyed) return;

    if (isPlayerWin) {
      this.sceneEvents.emit("soundEffect", SoundEffect.gameWinMusic);
      scene.children.bringToTop(this.shipIcon);
      InputBlocker.disableInput(this.props.scene);
      Animator.addShipFloatAnimation({
        shipIcon: this.shipIcon,
        targetX: this.islandIcon.getBounds().left - 16,
        onComplete: () => {
          this.showWinBonusAnimation(winBonusCoins, () => this.onWinBonusAnimationFinish());
        },
      });
    } else {
      InputBlocker.disableInput(this.props.scene);
      this.sceneEvents.emit("soundEffect", SoundEffect.explode);
      scene.cameras.main.shake(gameOverEffectFailDelay, 0.05);
      Animator.addShipSinkAnimation({
        shipIcon: this.shipIcon,
        duration: 1750,
        onComplete: () => {
          InputBlocker.enableInput(this.props.scene);
          this.logic.onViewSignal("onGameOverAnimationFinish", {
            isPlayerWin,
          });
        },
      });
    }
  }

  private showWinBonusAnimation(winBonus: number, onComplete: () => void) {
    /** полет монеток от сундука к счетчика за лимит времени **/

    const { scene, cellSize } = this.props;
    const maxAmount = 15;
    const coinsAmount = Math.min(winBonus, maxAmount);

    const baseCoinsValue = Math.floor(winBonus / coinsAmount);
    const lastCoinAddValue = winBonus - coinsAmount * baseCoinsValue;

    /** добавляем монетки **/
    const { centerX, centerY } = this.islandIcon.getBounds();
    const coins = Array.from({ length: coinsAmount }, (_, i) => {
      const isLastCoin = i === coinsAmount - 1;
      const coinsValue = isLastCoin ? baseCoinsValue + lastCoinAddValue : baseCoinsValue;
      const coinView = new CoinView({
        scene,
        size: cellSize * 0.9,
        x: centerX,
        y: centerY,
        coinsValue,
        textureName: this.assetsBuilder.atlas.pngUrl,
        frameName: this.assetsBuilder.atlas.frames.icon_money_128.filename,
      });
      return coinView;
    });

    /** чтобы монетки были ниже острова **/
    scene.children.bringToTop(this.islandIcon);
    scene.children.bringToTop(this.shipIcon);

    /** запускаем в полет **/
    this.addCoinsFlyToTarget(coins, onComplete);
  }

  private onWinBonusAnimationFinish() {
    InputBlocker.enableInput(this.props.scene);
    this.logic.onViewSignal("onGameOverAnimationFinish", {
      isPlayerWin: true,
    });
  }

  private onCellArrayRevealed(cells: SimpleCell[]) {
    const { minesweeper } = this;
    if (this.isDestroyed) return;

    const { totalMines, flaggedMines } = minesweeper.getFieldState();
    this.logic.onViewSignal("onCellArrayRevealed", { totalMines, flaggedMines });
    this.runCoinsFlyAnimation(cells);
  }

  private runCoinsFlyAnimation(cells: CellView[]) {
    const freeLootCells = cells.filter((cell) => !cell.cell.isMine && cell.cell.loot?.type === "coins");
    const coins = freeLootCells.map(
      (cell) => {
        const { centerX, centerY } = cell.getBounds();
        return new CoinView({
          scene: this.props.scene,
          size: this.props.cellSize * 0.9,
          x: centerX,
          y: centerY,
          coinsValue: cell.cell.loot?.value ?? 1,
          textureName: this.assetsBuilder.atlas.pngUrl,
          frameName: this.assetsBuilder.atlas.frames.icon_money_128.filename,
        })
      },
    );

    coins.forEach((coin) => Animator.addIdleCoinAnimation(coin));
    this.addCoinsFlyToTarget(coins);
  }

  private addCoinsFlyToTarget(coins: Phaser.GameObjects.Image[], onComplete?: () => void) {
    const onCoinFinished = (coin: Phaser.GameObjects.Image) => {
      if (this.isDestroyed) return;
      const coinValue = coin.getData("coinValue") ?? 1;
      this.logic.onViewSignal("onCoinFinished", { coinValue });
      this.sceneEvents.emit("soundEffect", SoundEffect.coinFlip);
    };

    const onAllCoinsFinished = () => {
      if (this.isDestroyed) return;
      this.logic.onViewSignal("onAllCoinFinished", undefined);
      onComplete?.();
    };

    const totalFlyDuration = this.props.coinsFlyMaxDuration;
    const coinDelay = 0;
    const coinTarget = this.getCoinFlyTarget();
    Animator.addCoinsFlyToTarget(coins, coinTarget, coinDelay, totalFlyDuration, onCoinFinished, onAllCoinsFinished);
  }

  private getCoinFlyTarget() {
    const { width, height } = getCanvasSize(this.props.scene);

    return {
      x: Math.round(0.8 * width),
      y: Math.round(0.08 * height),
    };
  }
}
