import { Align } from "@kvisaz/phaser-sugar";
import { getLocalizedText } from "../../assets";
import { uiIconBackButton, uiIconSettingsButton, UiMineCounter, UiMoneyCounter } from "../../ui";
import { Scenes } from "../routes";

interface IProps {
  scene: Phaser.Scene;
}

export class GameUi {
  private readonly mineCounter: UiMineCounter;
  private readonly moneyCounter: UiMoneyCounter;

  constructor({ scene }: IProps) {
    const align = new Align();

    /** header backbutton **/
    const backButton = uiIconBackButton({
      scene,
      isAutoScenePlace: true,
      route: Scenes.LevelMap,
      exitDialog: {
        title: getLocalizedText("backDialog.game.Title"),
        text: getLocalizedText("backDialog.Info"),
      },
    });
    scene.add.existing(backButton);

    /** settings button **/
    const uiSettingsButton = uiIconSettingsButton({ scene });
    scene.add.existing(uiSettingsButton);
    align.anchorSceneScreen(scene).rightIn(uiSettingsButton, -20).topIn(uiSettingsButton, 20);

    /** mineCounter **/
    const mineCounter = new UiMineCounter({ scene, isAutoPlace: false });
    this.mineCounter = mineCounter;
    scene.add.existing(mineCounter);
    align.anchor(backButton).centerY(mineCounter).rightTo(mineCounter, 20);


    /** moneyCounter **/
    const moneyCounter = new UiMoneyCounter({
      scene,
    });
    this.moneyCounter = moneyCounter;
    scene.add.existing(moneyCounter);
    align.anchor(uiSettingsButton).centerY(moneyCounter).leftTo(moneyCounter, -20);
  }

  setMoney(value: number) {
    this.moneyCounter.setValue(value);
  }

  setMines(value: number) {
    this.mineCounter.setValue(value);
  }
}
