/**
 * В один конфиг собираю и деньги, и мины
 * чтобы проще было балансить
 * **/
const balanceConfig = {
  levelAmount: 21,
  /**
   * базовые константы для расчета дохода и стоимости открытия следующего уровня
   * - income - доход текущего уровня
   * - cost - стоимость открытия следующего уровня
   *  протестировано в balance_sandbox.html именно для этого числа уровней
   *  **/
  levelCoins: {
    incomeBase: 2.2,
    incomeBaseStab: 5.5,
    incomeGrowth: 1.23,
    costBase: 1.3,
    costBaseStab: 5,
    costGrowth: 1.4,
  },
  /** сколько можно выдать за счет монеток на поле от общего дохода **/
  freeCoinsPartOfIncome: 0.45,
  /** плотность распределения мин - на все ячейки **/
  cellsPerMine: {
    firstLevel: 11,
    lastLevel: 11,
  },
};

function levelIncomeExp(levl: number, incomeBase: number, incomeGrowth: number, incomeBaseStab: number) {
  return Math.floor(incomeBase * incomeGrowth ** (levl - 1) + incomeBaseStab);
}

function levelCostExp(levl: number, costBase: number, costGrowth: number, costBaseStab: number) {
  return Math.ceil(costBase * costGrowth ** (levl - 1) + costBaseStab);
}

function levelIncome(level: number) {
  return levelIncomeExp(
    level,
    balanceConfig.levelCoins.incomeBase,
    balanceConfig.levelCoins.incomeGrowth,
    balanceConfig.levelCoins.incomeBaseStab,
  );
}

/** при расчете интераций учитываем, что начальный currentNumber для firstSample = 0 **/
function getIteration(currentNumber: number, lastNumber: number, firstSample: number, lastSample: number) {
  const part = currentNumber / lastNumber;
  return Math.round(firstSample + part * (lastSample - firstSample));
}

function cellsPerMine(level: number) {
  return getIteration(
    level,
    balanceConfig.levelAmount - 1,
    balanceConfig.cellsPerMine.firstLevel,
    balanceConfig.cellsPerMine.lastLevel,
  );
}

function levelMineAmount({ columns, rows, level }: { columns: number; rows: number; level: number }) {
  return Math.floor((columns * rows) / cellsPerMine(level));
}

export const balance = {
  levelAmount: balanceConfig.levelAmount,
  levelMineAmount,
  freeCoinsPartOfIncome: balanceConfig.freeCoinsPartOfIncome,
  levelIncome,
  levelCost: (level: number) =>
    levelCostExp(
      level,
      balanceConfig.levelCoins.costBase,
      balanceConfig.levelCoins.costGrowth,
      balanceConfig.levelCoins.costBaseStab,
    ),
};
