import { fitToSize } from "../../common";

interface IProps {
  x: number;
  y: number;
  size: number;
  scene: Phaser.Scene;
  coinsValue: number;
  textureName: string;
  frameName: string;
}

export class CoinView extends Phaser.GameObjects.Image {
  public readonly coinValue: number;

  constructor(props: IProps) {
    super(props.scene, props.x, props.y, props.textureName, props.frameName);
    fitToSize({ gameObject: this, width: props.size, height: props.size });
    this.coinValue = props.coinsValue;
    this.setOrigin(0.5, 0.5);
    props.scene.add.existing(this);
  }
}
