import { PreloadTask } from "@kvisaz/phaser-sugar";
import { Router, Scenes } from "../routes";
import { ASSETS } from "../../assets";
import { services } from "../../serviceProvider";
import { addHtmlLoaderToPhaser } from "../../common";
import { globalEvents } from "../../globalEvents";

export class BootScene extends Phaser.Scene {
  constructor() {
    super(Scenes.Boot);
  }

  preload() {
    addHtmlLoaderToPhaser({
      scene: this,
      loaderVarHosId: "loader",
      cssVarProgressName: "--progress",
    });

    ASSETS.bootPreload(this);

    globalEvents.emit('bootSceneStart');

    /** синхронизация сервисов - базы данных, ysdk и так далее **/
    const dataBasePromise = services.preload();
    PreloadTask.load(this, dataBasePromise);
  }

  create() {
    new Router(this).go(Scenes.Start);
  }
}
