import { GameObject, getCanvasSize } from "../../../common";
import { mineSweeperDisplayConfig } from "../config";
import { Align } from "@kvisaz/phaser-sugar";

type Point = { x: number; y: number };

interface IAddFlyArgs {
  coin: Phaser.GameObjects.Image;
  target: Point;
  delay?: number;
  onCoinFinished?: () => void;
}

export class Animator {
  static addIdleCoinAnimation(coin: Phaser.GameObjects.Image) {
    const { scene } = coin;
    const baseDelay = Phaser.Math.Between(0, 1000); // Random start delay for each coin
    const baseScale = coin.scale;

    scene.tweens.add({
      targets: coin,
      scaleX: 0.7 * baseScale, // Сжимаем по горизонтали для эффекта поворота
      duration: 350,
      ease: "Sine.easeInOut",
      yoyo: true,
      repeat: -1,
      delay: baseDelay,
    });
  }

  static addCoinFlyTo({ coin, onCoinFinished, target, delay = 350 }: IAddFlyArgs) {
    const { scene } = coin;
    const coinBounds = coin.getBounds();
    const baseScale = coin.scale;
    const startY = coin.y;
    const { x: endX, y: endY } = target;
    const jumpHeight = coinBounds.height * 0.35;

    scene.time.delayedCall(delay, () => {
      scene.tweens.killTweensOf(coin);

      scene.tweens.chain({
        targets: coin,
        tweens: [
          {
            y: startY - jumpHeight,
            duration: 120 * baseScale,
            yoyo: true,
          },
          {
            x: endX,
            y: endY,
            // scaleX: 0.5 * baseScale,
            // scaleY: 0.5 * baseScale,
            delay: 150,
            duration: 350,
            ease: Phaser.Math.Easing.Cubic.Out,
          },
        ],
        onComplete: () => {
          onCoinFinished?.();
          coin.destroy();
        },
      });
    });
  }

  static addCoinsFlyToTarget(
    coins: Phaser.GameObjects.Image[],
    target: Point,
    initialDelay = 550,
    totalDuration = 2000,
    onCoinFinished?: (coin: Phaser.GameObjects.Image) => void,
    onAllFinished?: () => void,
  ) {
    if (!coins.length) return;

    // последовательный улет с
    const fastestDelay = totalDuration / (coins.length - 1);
    const sequenceDelay = Math.min(mineSweeperDisplayConfig.coinsFlyInterval, fastestDelay);

    coins.forEach((coin, index) => {
      const isLast = index === coins.length - 1;
      this.addCoinFlyTo({
        coin,
        target,
        delay: initialDelay + index * sequenceDelay,
        onCoinFinished: () => {
          onCoinFinished?.(coin);
          if (isLast) onAllFinished?.();
        },
      });
    });
  }

  static asyncTween(scene: Phaser.Scene, config: Phaser.Types.Tweens.TweenBuilderConfig) {
    return new Promise<void>((resolve) => {
      scene.tweens.add({
        ...config,
        onComplete: (tween, targets, param) => {
          config.onComplete?.(tween, targets, param);
          resolve();
        },
      });
    });
  }

  static async slide(obj: GameObject, dx: number = 0, dy: number = 0, duration: number = 300) {
    const { scene } = obj;
    return Animator.asyncTween(scene, {
      targets: obj,
      x: obj.x + dx,
      y: obj.y + dy,
      duration,
      ease: Phaser.Math.Easing.Cubic.In,
    });
  }

  static async slideScreenIn(obj: GameObject, duration = 120) {
    const { scene } = obj;
    const sceneBounds = getCanvasSize(scene);

    new Align().anchorSceneScreen(scene).center(obj).bottomTo(obj);

    return Animator.slide(obj, 0, -sceneBounds.height, duration);
  }

  static addShipIdleAnimation(shipIcon: Phaser.GameObjects.Image) {
    const { scene } = shipIcon;
    scene.tweens.add({
      targets: [shipIcon],
      props: {
        y: shipIcon.y - 12,
      },
      yoyo: true,
      loop: -1,
      duration: 1000,
    });
  }


  static addShipRockAnimation(shipIcon: Phaser.GameObjects.Image) {
    const { scene } = shipIcon;
    shipIcon.angle = -2;
    scene.tweens.add({
      targets: [shipIcon],
      props: {
        angle: 2,
      },
      yoyo: true,
      loop: -1,
      duration: 1250,
    });
  }

  static addShipFloatAnimation({ onComplete, targetX, shipIcon }: { onComplete: () => void, shipIcon: Phaser.GameObjects.Image, targetX: number }) {
    const { scene } = shipIcon;

    scene.tweens.add({
      targets: [shipIcon],
      props: {
        x: targetX - 32,
      },
      duration: 1500,
      onComplete,
    });
  }

  static addShipSinkAnimation({ duration, onComplete, shipIcon }: { duration: number, onComplete: () => void, shipIcon: Phaser.GameObjects.Image }) {
    const { scene } = shipIcon;

    scene.tweens.add({
      targets: [ shipIcon ],
      props: {
        // переворот на 180°
        angle: 180,
        // опустить вниз на 200px
        y: shipIcon.y + 200
      },
      duration,
      ease: 'Linear',
      repeat: 0,
      onComplete
    });
  }
}
