import { Align } from "@kvisaz/phaser-sugar";
import { ASSETS, getLocalizedText } from "../../assets";
import { Router } from "../routes";
import { fitToSize, makeGrid } from "../../common";
import {
  Dialogs,
  InputBlocker,
  LevelButtonType,
  makeLevelButton,
  SceneBg,
  uiIconSettingsButton,
  UiMoneyCounter,
} from "../../ui";
import { ILevelData, ILevelMapLogic, ILevelMapView, ILogicInstruction } from "./logic/interfaces";
import { gameObjectButton } from "../../components/ui";
import { Animator } from "../../games/MineSweeper/utils";
import { SceneEvents } from "../../SceneEvents";

interface IProps {
  scene: Phaser.Scene;
  levelDatas: ILevelData[];
  columns: number;
  money: number;
}

export class LevelMapView implements ILevelMapView {
  logic!: ILevelMapLogic;

  private moneyCounter!: UiMoneyCounter;
  private levelContainer: Phaser.GameObjects.Container;
  private dialogBuilder: Dialogs;
  private shipIcon: Phaser.GameObjects.Image;
  private islandIcon: Phaser.GameObjects.Image;
  private sceneEvents: SceneEvents;

  constructor(private props: IProps) {
    const { scene } = this.props;
    const align = new Align();
    this.dialogBuilder = new Dialogs(scene);
    const assetsBuilder = ASSETS.images.builder(scene);
    this.sceneEvents = new SceneEvents(scene);

    /** start music in level map  **/
    this.sceneEvents.emit("musicPlay", undefined);

    /** bg **/
    new SceneBg({ scene });

    /** footer - island  **/
    const islandIcon = assetsBuilder.build.island_two_palms();
    scene.add.existing(islandIcon);
    this.islandIcon = islandIcon;

    /** footer - ship  **/
    const shipIcon = assetsBuilder.build.ship_2_macht();
    fitToSize({
      gameObject: shipIcon,
      width: 125,
      height: 125,
    });
    shipIcon.flipX = true;
    shipIcon.setOrigin(0.5, 1);
    scene.add.existing(shipIcon);
    this.shipIcon = shipIcon;

    /** settings button **/
    const uiSettingsButton = uiIconSettingsButton({ scene });
    scene.add.existing(uiSettingsButton);
    align.anchorSceneScreen(scene).rightIn(uiSettingsButton, -20).topIn(uiSettingsButton, 20);

    /** title **/
    const titleText = getLocalizedText("levelMap.Title");
    const title = scene.add.text(0, 0, titleText, {
      fontSize: 40,
      fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
      color: "#B6D4EF",
    });
    align.anchorSceneScreen(scene).centerX(title).topIn(title, 45);

    /** level buttons **/
    this.levelContainer = this.createLevelButtonContainer(this.props.levelDatas);

    /** money counter **/
    const moneyCounter = new UiMoneyCounter({
      scene,
      value: this.props.money,
    });
    this.moneyCounter = moneyCounter;
    scene.add.existing(moneyCounter);
    align.anchor(uiSettingsButton).centerY(moneyCounter).leftTo(moneyCounter, -20);

    align.anchorSceneScreen(scene).leftIn(shipIcon).bottomIn(shipIcon);
    align.anchorSceneScreen(scene).rightIn(islandIcon, 54).bottomIn(islandIcon, 54);

    /** animation after layour**/
    Animator.addShipRockAnimation(this.shipIcon);
  }

  init(logic: ILevelMapLogic) {
    this.logic = logic;
  }

  onLogicCommand<T extends keyof ILogicInstruction>(command: T, data: ILogicInstruction[T]) {
    switch (command) {
      case "levelBoughtClickReaction": {
        // остров открыт - запускаем игру
        const { levelData } = data as ILogicInstruction["levelBoughtClickReaction"];
        const { level } = levelData;

        InputBlocker.disableInput(this.props.scene);
        Animator.addShipFloatAnimation({
          shipIcon: this.shipIcon,
          targetX: this.islandIcon.getBounds().left - 32,
          onComplete: () => {
            InputBlocker.enableInput(this.props.scene);
            new Router(this.props.scene).showGameFromLevelMap({ level });
          },
        });
        break;
      }
      case "levelBuyClickReaction": {
        // остров можно купить - спрашиваем
        const { levelData, mode } = data as ILogicInstruction["levelBuyClickReaction"];
        InputBlocker.enableInput(this.props.scene);
        if (mode === "buy") {
          this.dialogBuilder.levelMapLevelBuy({
            money: levelData.level.levelNextCost,
            onOkClick: () => {
              this.logic.onViewSignal("onLevelBuyConfirm", { levelData });
            },
            onCancelClick: () => {},
          });
          break;
        }

        if (mode === "not_money") {
          this.dialogBuilder.levelMapLevelNoMoney({
            money: levelData.level.levelNextCost,
            onOkClick: () => {},
          });
          break;
        }

        if (mode === "not_opened") {
          this.dialogBuilder.levelMapLevelLocked({
            onOkClick: () => {},
          });
          break;
        }
        break;
      }
      case "onLevelBuySuccess": {
        InputBlocker.enableInput(this.props.scene);
        const { moneyTotal, levelDatas, buyedLevelId } = data as ILogicInstruction["onLevelBuySuccess"];
        this.sceneEvents.emit("savePlayerGold", moneyTotal);
        this.sceneEvents.emit("unlockLevel", { levelId: buyedLevelId });
        this.moneyCounter.setValue(moneyTotal);
        this.levelContainer.destroy();
        this.levelContainer = this.createLevelButtonContainer(levelDatas);
        break;
      }
      case "onLevelBuyError": {
        const errorData = data as ILogicInstruction["onLevelBuyError"];
        console.warn("onLevelBuyError", errorData);
        break;
      }
      default: {
        console.warn("unknown logic command", command, data);
      }
    }
  }

  private createLevelButtonContainer(levelDatas: ILevelData[]) {
    const { scene } = this.props;
    const levelContainer = new Phaser.GameObjects.Container(scene);
    const buttons = levelDatas.map((data, index) => {
      const { level, isMoneyEnough, isBuyAllowed, isUnlocked, isCompleted } = data;

      let type: LevelButtonType = "locked";
      if (isBuyAllowed) {
        type = isMoneyEnough ? "buyable" : "not_enough_money";
      }
      if (isUnlocked) {
        type = isCompleted ? "completed" : "current";
      }
      const buttonView = makeLevelButton({
        scene,
        levelNumber: index + 1,
        levelPrice: level.levelNextCost,
        type,
        size: 116,
      });

      gameObjectButton({
        gameObject: buttonView,
        inputTracker: buttonView.inputTracker,
        onClick: () => {
          this.onLevelButtonClick(data);
        },
        options: {
          once: false,
        },
      });

      return buttonView;
    });

    const bounds = buttons[0].getBounds();
    const cellWidth = bounds.width * 1.25;
    const cellHeight = bounds.height * 1.25;

    makeGrid({
      objects: buttons,
      unitInRow: this.props.columns,
      colStep: cellWidth,
      rowStep: cellHeight,
      centerLastRow: false,
      snake: false,
      evenRowOffsetX: 72,
    });
    levelContainer.add(buttons);

    new Align().anchorSceneScreen(scene).centerX(levelContainer).topIn(levelContainer, 178);

    scene.add.existing(levelContainer);

    return levelContainer;
  }

  private onLevelButtonClick(levelData: ILevelData) {
    InputBlocker.disableInput(this.props.scene);
    this.logic.onViewSignal("onLevelClick", { levelData });
  }
}
