import { IMineSweeperLevel } from "./interfaces";
import { forEach2D } from "../../../../common";

export class MineSweeperLevelTest {
  constructor(private level: IMineSweeperLevel) {
    console.log("MineSweeperLevelTest --------");
    this.checkMines();
    this.checkColumns();
    console.log("------- /MineSweeperLevelTest");
  }

  checkMines() {
    const { cellPlaces, minesAmount } = this.level;
    let realMinesAmount = 0;
    forEach2D(cellPlaces, (place) => {
      if (place?.isMine) realMinesAmount++;
    });
    if (minesAmount !== realMinesAmount) {
      console.warn(`minesAmount ${minesAmount}!== realMinesAmount ${realMinesAmount}`);
      return;
    }

    console.log("checkMines pass");
  }

  checkColumns() {
    const { cellPlaces, columns, rows } = this.level;
    if (cellPlaces.length !== columns) {
      console.warn(`cellPlaces.length ${cellPlaces.length} !== columns ${columns}`);
      return;
    }
    if (cellPlaces[0].length !== rows) {
      console.warn(`cellPlaces[0].length ${cellPlaces.length} !== rows ${rows}`);
      return;
    }
    console.log("checkColumns pass");
  }
}
