import { ILevel } from "../../interfaces";
import { ILevelData, ILevelMapLogic, ILevelMapState, ILevelMapView, IViewSignals } from "./interfaces";
import { ISingleLevelSaveData } from "./contracts";

interface IProps {
  levels: ILevel[];
  playerGold: number;
  levelSaves: Record<number, ISingleLevelSaveData | undefined>;
}

export class LevelMapLogic implements ILevelMapLogic {
  state: ILevelMapState;
  view!: ILevelMapView;

  constructor(private props: IProps) {
    const { playerGold } = this.props;
    this.state = {
      moneyTotal: playerGold,
      levelDatas: this.getLevelDatas(),
    };
  }

  init(view: ILevelMapView) {
    this.view = view;
  }

  onViewSignal<T extends keyof IViewSignals>(signal: T, data: IViewSignals[T]) {
    const { moneyTotal } = this.state;
    switch (signal) {
      case "onLevelClick": {
        const { levelData } = data as IViewSignals["onLevelClick"];
        const { level, isUnlocked, isBuyAllowed } = levelData;
        /** проверка что разлочен **/
        if (isUnlocked) {
          this.view.onLogicCommand("levelBoughtClickReaction", { levelData });
          break;
        }

        /** проверка что остров доступен для покупки **/
        if (!isBuyAllowed) {
          const message = `Вы еще не нашли дорогу к этому острову`;
          this.view.onLogicCommand("levelBuyClickReaction", { levelData, message, mode: "not_opened" });
          break;
        }

        /** проверка что не хватает денег **/
        const isNotEnoughMoney = moneyTotal < level.levelNextCost;
        if (isNotEnoughMoney) {
          const delta = level.levelNextCost - moneyTotal;
          const message = `Не хватает денег на остров ${level.id}. У вас ${moneyTotal} монет. Надо еще ${delta} монет.`;
          this.view.onLogicCommand("levelBuyClickReaction", { levelData, message, mode: "not_money" });
          break;
        }
        /** денег  хватает **/
        const message = `Вы готовы потратить ${level.levelNextCost} монет на остров?`;
        this.view.onLogicCommand("levelBuyClickReaction", { levelData, message, mode: "buy" });
        break;
      }
      case "onLevelBuyCancel": {
        // const { levelData } = data as IViewSignals["onLevelBuyCancel"];
        // const message = `покупка острова ${levelData.level.id} отменена.`;
        // console.log(message);
        break;
      }
      case "onLevelBuyConfirm": {
        /** покупка **/
        const { levelData } = data as IViewSignals["onLevelBuyConfirm"];
        const { level } = levelData;

        /** купленный остров просто помечается как разлоченный **/
        try {
          this.state = {
            ...this.state,
            moneyTotal: moneyTotal - level.levelNextCost,
            levelDatas: this.state.levelDatas.map((levelData) => {
              return {
                ...levelData,
                isUnlocked: levelData.isUnlocked || levelData.level.id === level.id,
              };
            }),
          };

          this.view.onLogicCommand("onLevelBuySuccess", {
            levelDatas: this.state.levelDatas,
            moneyTotal: this.state.moneyTotal,
            buyedLevelId: level.id,
          });
        } catch (e) {
          console.warn(e);
          this.view.onLogicCommand("onLevelBuyError", { message: "Ошибка при покупке острова" });
        }
        break;
      }
      default: {
        console.warn("unknown signal ", signal, data);
      }
    }
  }

  private getLevelDatas(): ILevelData[] {
    const { levels, levelSaves, playerGold } = this.props;

    return levels.map((level) => {
      // сейчас id - это  индекс. Это не очень надежно
      const levelIndex = level.id;
      const prevLevel = levels[levelIndex - 1] as ILevel | undefined;
      // а тут доступ как id
      const levelSave = levelSaves[level.id];

      const isFirstLevel = prevLevel == null;
      /** разлочен всегда первый уровень, а также уровень, который был разлочен ранее **/
      const isUnlocked = isFirstLevel || levelSave?.isUnlocked === true;

      const isMoneyEnough = level.levelNextCost <= playerGold;

      /** можно купить, если предыдущий уровень был выигран хотя бы 1 раз **/
      const isBuyAllowed = prevLevel != null && levelSaves[prevLevel.id]?.isWinSometime === true;

      const isCompleted = levelSave?.isWinSometime ?? false;

      return {
        level,
        isMoneyEnough,
        isBuyAllowed,
        isUnlocked,
        isCompleted
      };
    });
  }

  private getUnlockedLevels(state: ILevelMapState) {
    return state.levelDatas.filter((data) => data.isUnlocked).map((data) => data.level.id);
  }
}
