import { ASSETS } from "../../assets";
import { gameObjectButton } from "../../components/ui";
import { Dialogs } from "../Dialogs";
import { SceneEvents, SoundEffect } from "../../SceneEvents";

interface IProps {
  scene: Phaser.Scene;
}

export function uiIconSettingsButton({ scene }: IProps) {
  const builder = ASSETS.images.builder(scene);

  const gameObject = builder.build.button_settings();

  const onClick = () => {

    new Dialogs(scene).settings({
      title: "Settings",
      onOkClick: () => {},
    });
  };

  const sceneEvents = new SceneEvents(scene);
  return gameObjectButton({
    gameObject,
    inputTracker: gameObject,
    onClick: () => {
      sceneEvents.emit("soundEffect", SoundEffect.click);
      onClick();
    },
    onOver: () => {
      sceneEvents.emit("soundEffect", SoundEffect.buttonHover);
      },
    options: {
      once: false,
      overMoveY: 4,
      clickMode: "up",
    },
  }) as Phaser.GameObjects.Image;
}
