import { Align } from "@kvisaz/phaser-sugar";
import { Scenes } from "../scenes/routes";
import { ASSETS } from "../assets";

interface IProps {
  scene: Phaser.Scene;
}

export class SceneBg {
  private scene: Phaser.Scene;

  constructor({ scene }: IProps) {
    this.scene = scene;
    const bgBuilder = ASSETS.images.builder(scene);
    switch (scene.scene.key as Scenes) {
      case "Start": {
        this.addToScene(bgBuilder.build.bg_start());
        break;
      }
      default: {
        this.addToScene(bgBuilder.build.bg_waves());
      }
    }
  }

  private addToScene(bg: Phaser.GameObjects.Image) {
    const { scene } = this;
    scene.add.existing(bg);
    const align = new Align();
    align.anchorSceneScreen(scene).center(bg);
  }
}
