import { Align } from "@kvisaz/phaser-sugar";
import { ASSETS } from "../../assets";

interface IProps {
  scene: Phaser.Scene;
  value?: number;
  isAutoPlace: boolean;
}

export class UiMineCounter extends Phaser.GameObjects.Container {
  private text: Phaser.GameObjects.Text;

  constructor(private props: IProps) {
    super(props.scene);
    const { scene, value } = props;
    const assetBuilder = ASSETS.images.builder(scene);

    const bg = assetBuilder.build.nine_light_blue_stroked(154, 80);
    const icon = assetBuilder.build.icon_mine();

    const text = new Phaser.GameObjects.Text(scene, 0, 0, `${value}`, {
      fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
      fontSize: "50px",
      color: "#23394C",
      align: "left",
    }).setOrigin(0);
    this.text = text;

    const align = new Align();
    align.anchor(bg).centerY(icon).leftIn(icon, -64);
    align.anchor(icon).centerY(text).rightTo(text, 0);

    this.add([bg, icon, text]);

    if (this.props.isAutoPlace) {
      align.anchorSceneScreen(scene).rightIn(this, -20).topIn(this, 20);
    }
  }

  setValue(value: number) {
    const text = value.toString();
    if (this.text.text === text) return;
    this.text.setText(value.toString());
  }
}
