import { IStorage } from "./contracts";
import { IGameStats, ISingleLevelSaveData } from "./interfaces";

interface IProps {
  database: IStorage;
}

const createDefaultGameStats = (): IGameStats => ({
  player: { gold: 0 },
  levels: {},
});

export class MetaGameStats {
  private key = "metagame";
  private stats: IGameStats;

  constructor(private props: IProps) {
    this.stats = createDefaultGameStats();
  }

  public load() {
    const dbData = this.props.database.get<IGameStats>({ key: this.key });
    if (dbData == null) return;
    this.stats = {
      player: { gold: typeof dbData.player.gold === "number" ? dbData.player.gold : 0 },
      levels: dbData.levels,
    };
  }

  private save() {
    this.props.database.set({ key: this.key, data: this.stats });
  }

  getPlayerGold(): number {
    return this.stats.player.gold;
  }

  getSavedLevels(): Record<number, ISingleLevelSaveData | undefined> {
    return this.stats.levels;
  }

  getSavedLevel(levelId: number): ISingleLevelSaveData | undefined {
    const saveData = this.stats.levels[levelId];
    if (saveData == null) return undefined;
    return {
      ...saveData,
    };
  }

  setPlayerGold(gold: number) {
    this.stats.player.gold = Math.max(0, gold);
    this.save();
  }

  /** внутрь публичных методов */
  private isValidLevelId(id: number): boolean {
    return Number.isInteger(id) && id >= 0;
  }

  /** Меняем только 1 поле, остальные оставляем **/
  unlockLevel(levelId: number) {
    if (!this.isValidLevelId(levelId)) return;

    const saveData = this.stats.levels[levelId] ?? {};
    this.stats.levels[levelId] = {
      ...saveData,
      levelId,
      isUnlocked: true,
    };
    this.save();
  }

  /** Прошли 1 уровень, меняем только его указанные поля**/
  saveLevelPlay({ levelId, isPlayerWin }: { levelId: number; isPlayerWin: boolean }) {
    const saveData = this.stats.levels[levelId];

    const addWin = isPlayerWin ? 1 : 0;
    const plays = saveData?.plays != null ? saveData.plays + 1 : 1;
    const wins = saveData?.wins != null ? saveData.wins + addWin : addWin;
    const lastPlay = { isWin: isPlayerWin, dateMs: Date.now() };

    const updatedLevelSaveData: ISingleLevelSaveData = {
      levelId,
      isWinSometime: saveData?.isWinSometime || isPlayerWin,
      isUnlocked: saveData?.isUnlocked,
      plays,
      wins,
      lastPlay,
    };

    this.stats.levels[levelId] = updatedLevelSaveData;
    this.save();
  }
}
