import { IMineSweeperLevelCell } from "./logic/customMineField/interfaces";
import { MineCellImageBuilder } from "./interfaces";

interface CellProps {
  scene: Phaser.Scene;
  cellSize: number;
  cell: IMineSweeperLevelCell;
  onCellDown: (cell: SimpleCell) => void;
  onClick: (cell: SimpleCell) => void;
  onRightClick: (cell: SimpleCell) => void;
  imageBuilder: MineCellImageBuilder;
}

export class SimpleCell extends Phaser.GameObjects.Container {
  private cellBg: Phaser.GameObjects.Image;
  private cellClosed: Phaser.GameObjects.Image;
  private flagImage: Phaser.GameObjects.Image;
  private mineImage: Phaser.GameObjects.Image;
  private text: Phaser.GameObjects.Text;
  private pressTimer: NodeJS.Timeout | null = null;

  get cell(): IMineSweeperLevelCell {
    return this.props.cell;
  }

  get row(): number {
    return this.props.cell.row;
  }

  get col(): number {
    return this.props.cell.column;
  }

  constructor(private props: CellProps) {
    super(props.scene, props.cell.column * props.cellSize, props.cell.row * props.cellSize);
    const { cellSize: size } = props;

    // Create all image variants
    this.cellBg = this.props.imageBuilder.cellBg().setDisplaySize(size, size).setVisible(true);
    this.cellClosed = this.props.imageBuilder.cellClosed().setDisplaySize(size, size);
    this.flagImage = this.props.imageBuilder.flag().setDisplaySize(size, size).setVisible(false);
    this.mineImage = this.props.imageBuilder.mine().setDisplaySize(size, size).setVisible(false);

    // Set up interactivity
    this.cellBg
      .setInteractive({
        useHandCursor: true,
      })
      .on("pointerdown", (pointer: Phaser.Input.Pointer) => {
        const ev = pointer.event as MouseEvent;
        if (ev.button === 2) return;
        this.props.onCellDown(this);
        this.pressTimer = setTimeout(() => {
          this.props.onRightClick(this);
          this.pressTimer = null;
        }, 500); // 500 мс для долгого нажатия
      })
      .on("pointerup", (pointer: Phaser.Input.Pointer) => {
        if (this.pressTimer) {
          clearTimeout(this.pressTimer);
          this.pressTimer = null;
          this.props.onClick(this);
          return;
        }
        const ev = pointer.event as MouseEvent;
        // 2 → правая кнопка мыши
        if (ev.button === 2) {
          this.props.onRightClick(this);
        }

      })
      .on("pointerout", () => {
        if (this.pressTimer) {
          clearTimeout(this.pressTimer);
          this.pressTimer = null;
        }
      });

    // Текст для отображения числа соседних мин
    const { adjacentMines } = this.props.cell;
    const cellText = adjacentMines > 0 ? `${adjacentMines}` : "";
    const fontSize = `${size * 0.6}px`;
    this.text = this.props.imageBuilder.text(cellText);
    this.text
      .setOrigin(0.5)
      .setVisible(false)
      .setFontSize(fontSize)

    this.add([this.cellBg, this.cellClosed, this.flagImage, this.mineImage, this.text]);
    this.setSize(size, size);

    const x = props.cell.column * props.cellSize;
    const y = props.cell.row * props.cellSize;
    this.setPosition(x + size / 2, y + size / 2);
  }

  /** многократное вскрытие ячеек - то есть может быть вызвано много раз за 1 клик **/
  reveal() {
    const { isMine, adjacentMines } = this.cell;
    this.cellClosed.setVisible(false);
    this.flagImage.setVisible(false);

    if (isMine) {
      this.mineImage.setVisible(true);
    } else {
      if (adjacentMines > 0) {
        this.text.setText(adjacentMines.toString()).setVisible(true);
      }
    }
  }

  toggleFlag() {
    this.flagImage.setVisible(!this.flagImage.visible);
    this.cell.isFlagged = !this.cell.isFlagged;
  }
}
