import { YandexGamesService } from "./YandexGamesService";
import { AdsService } from "./AdsService";
import { IAdSettings } from "../interfaces";
import { GameDataService } from "./GameDataService";
import { SoundMusicSettings } from "./SoundMusicSettings";
import { setLocaleFromString } from "../assets";

interface IProps {
  gameId: string;
  adSettings: IAdSettings;
}

export class ServiceProvider {
  /**  AdsService - обертка над рекламой **/
  public readonly adsService: AdsService;

  /** универсальная база игры - сохраняй в ней по ключам что хочешь **/
  public readonly gameDataService: GameDataService;

  public readonly soundMusicSettings: SoundMusicSettings;
  private readonly yandexGamesService: YandexGamesService;

  constructor(private props: IProps) {
    const onYsdkInitSuccess = (lang: string) => {
      setLocaleFromString(lang);
    };

    /** напрямую не используется
     * используй систему global events для подписок для YSDK **/
    this.yandexGamesService = new YandexGamesService({
      onInitSuccess: onYsdkInitSuccess,
    });

    // сложные сервисы с зависимостями от других
    this.adsService = new AdsService({
      gameId: this.props.gameId,
      yandexGamesService: this.yandexGamesService,
      adSettings: this.props.adSettings,
    });

    this.gameDataService = new GameDataService({
      gameId: this.props.gameId,
      playerId: "DefaultHero",
    });

    this.soundMusicSettings = new SoundMusicSettings({
      cloudStorage: this.gameDataService,
    });
  }

  /** засунуть сюда все что требует загрузки **/
  public preload(): Promise<void[]> {
    return Promise.all([
      this.gameDataService.preload(),
      this.yandexGamesService.init(),
    ])
  }
}
