import { Align } from "@kvisaz/phaser-sugar";
import { LayoutUtils } from "../../common";
import { atlasDesignV4 } from "./atlasDesignV4";

interface IProps {
  scene: Phaser.Scene;
}

export class MainAtlas {
  public atlas = atlasDesignV4;
  public backgrounds = {
    bg_start: {
      url: "./assets/images/bg_start.png",
    },
    bg_waves: {
      url: "./assets/images/bg_waves.png",
    },
  };

  constructor(private props: IProps) {}

  public preload() {
    const { atlas, backgrounds } = this;
    const { scene } = this.props;
    scene.load.atlas(atlas.pngUrl, atlas.pngUrl, atlas.jsonUrl);
    Object.values(backgrounds).forEach((bg) => {
      scene.load.image(bg.url, bg.url);
    });
  }

  public build = {
    bg_start: () => this.createBg(this.backgrounds.bg_start.url),
    bg_waves: () => this.createBg(this.backgrounds.bg_waves.url),
    button_accent: (width = 320, height = 80) => this.createNineSlice("button_accent.png", width, height, 16),
    button_blue: (width = 320, height = 80) => this.createNineSlice("button_blue.png", width, height, 16),
    button_back: () => this.createAtlasImage("button-back.png"),
    button_sound_off: () => this.createAtlasImage("button-sound-off.png"),
    button_sound_on: () => this.createAtlasImage("button-sound-on.png"),
    button_music_on: () => this.createAtlasImage("button-music-on.png"),
    button_music_off: () => this.createAtlasImage("button-music-off.png"),
    button_settings: () => this.createAtlasImage("button_settings.png"),
    buy_button_bg: () => this.createAtlasImage("icon_buy_button_bg.png"),
    buy_button_bg_nineslice: (width = 90, height = 32) =>
      this.createNineSlice("icon_buy_button_bg.png", width, height, 16),
    buy_button_current: () => this.createAtlasImage("button_round_purple_dream_236x241.png"),
    icon_lock: ()=> this.createAtlasImage('icon_lock_small.png'),
    cell_closed_gray: () => this.createAtlasImage("cell_closed_gray.png"),
    cell_closed_sand_01: () => this.createAtlasImage("cell_closed_sand_01.png"),
    cell_marked: () => this.createAtlasImage("cell_marked.png"),
    cell_revealed_gray: () => this.createAtlasImage("cell_revealed_gray.png"),
    cell_revealed_sand: () => this.createAtlasImage("cell_revealed_sand.png"),
    dialog_frame_blue_light: (width = 728, height = 332) =>
      this.createNineSlice("dialog_frame_blue_light.png", width, height, 16),
    dialog_frame_blue_middle: (width = 770, height = 464) =>
      this.createNineSlice("dialog_frame_blue_middle.png", width, height, 16),
    icon_crush_random: () => {
      const textures = [
        "icon_crush_01.png",
        "icon_crush_02.png",
        "icon_crush_03.png",
        "icon_crush_04.png",
        "icon_crush_05.png",
      ];
      const texture = Phaser.Utils.Array.GetRandom(textures);
      return this.createAtlasImage(texture);
    },
    icon_crush_01: () => this.createAtlasImage("icon_crush_01.png"),
    icon_crush_02: () => this.createAtlasImage("icon_crush_02.png"),
    icon_crush_03: () => this.createAtlasImage("icon_crush_03.png"),
    icon_crush_04: () => this.createAtlasImage("icon_crush_04.png"),
    icon_crush_05: () => this.createAtlasImage("icon_crush_05.png"),
    icon_mine: () => this.createAtlasImage("icon_mine.png"),
    icon_money_128: () => this.createAtlasImage("icon_money_128.png"),
    icon_mark_green: () => this.createAtlasImage("icon_mark_green.png"),
    icon_island_palm_single: () => this.createAtlasImage("sprites_islands_r3_c11.png"),
    icon_island_chest: () => this.createAtlasImage("sprites_islands_r9_c15.png"),
    island_two_palms: () => this.createAtlasImage("island_two_palms.png"),
    nine_light_blue: (width = 155, height = 80) => this.createNineSlice("nine_light_blue.png", width, height, 16),
    nine_light_blue_stroked:  (width = 155, height = 80) => this.createNineSlice("nine_light_blue_stroked.png", width, height, 16),
    island_level: () => this.createAtlasImage("nine_island_level.png"),
    island_level_nineslice: (width = 128, height = 128) => this.createNineSlice("nine_island_level.png", width, height, 16),
    island_level_nineslice_current: (width = 128, height = 128) => this.createNineSlice("nine_island_level_current.png", width, height, 16),

    tile_bg_blue: () => this.createAtlasImage("tile_bg_blue.png"),
    ship_2_macht: () => this.createAtlasImage("ship_2_macht.png"),
  };

  private createAtlasImage(frameName: string): Phaser.GameObjects.Image {
    return new Phaser.GameObjects.Image(this.props.scene, 0, 0, this.atlas.pngUrl, frameName);
  }

  private createBg(bgUrl: string): Phaser.GameObjects.Image {
    return new Phaser.GameObjects.Image(this.props.scene, 0, 0, bgUrl);
  }

  private createNineSlice(
    frameName: string,
    width: number,
    height: number,
    padding: number,
  ): Phaser.GameObjects.NineSlice {
    return new Phaser.GameObjects.NineSlice(
      this.props.scene,
      0,
      0,
      this.atlas.pngUrl,
      frameName,
      width,
      height,
      padding,
      padding,
      padding,
      padding,
    );
  }
}

export class AtlasDesignPhaserAssetsTestScene extends Phaser.Scene {
  static KEY = `AtlasTestScene-${atlasDesignV4.pngUrl}`;

  constructor() {
    super(AtlasDesignPhaserAssetsTestScene.KEY);
  }

  preload() {
    new MainAtlas({ scene: this }).preload();
  }

  create() {
    const builder = new MainAtlas({ scene: this });
    const images = Object.values(builder.build).map((methodName) => {
      const image = methodName();
      this.add.existing(image);
      return image;
    });

    const columns = 8;
    const stepX = 250;
    const stepY = 150;
    const align = new Align();
    align.setPosition(images[0] as Phaser.GameObjects.Image, 0, 0);
    LayoutUtils.makeGridByColumn(images, columns, stepX, stepY);
  }
}
