import { Scenes } from "../routes";
import { GameView } from "./GameView";
import { IGameSceneData } from "../interfaces";
import { MineSweeperLevelFabric } from "../../components/Minesweeper/logic/customMineField";
import { GameLogic } from "./logic";
import { metaGame, services } from "../../serviceProvider";
import { SoundManager } from "../../ui";
import { SceneEvents } from "../../SceneEvents";
import { mineSweeperDisplayConfig } from "../../games/MineSweeper/config";
import { globalEvents } from "../../globalEvents";

export class GameScene extends Phaser.Scene {
  constructor() {
    super(Scenes.Game);
  }

  preload() {}

  create({ level }: IGameSceneData) {
    const { soundMusicSettings } = services;
    new SoundManager({ scene: this, soundMusicSettings });
    globalEvents.emit('gameSceneStart');

    this.subscribeMetaGame();
    const levelFabric = new MineSweeperLevelFabric();
    const gameLevel = levelFabric.createRoundedRectangle({
      ...level,
    });

    const gameView = new GameView({
      scene: this,
      level: gameLevel,
      levelId: level.id,
      cellSize: mineSweeperDisplayConfig.cellSize,
      coinsFlyMaxDuration: mineSweeperDisplayConfig.coinsFlyMaxDuration,
      gameOverEffectFailDelay: mineSweeperDisplayConfig.gameOverEffectFailDelay,
    });

    const playerGold = metaGame.getPlayerGold();
    const gameLogic = new GameLogic({
      minesAmount: level.minesAmount,
      playerGold,
      winBonusCoins: level.winBonusCoins ?? 0,
    });
    gameLogic.init(gameView);
    gameView.init(gameLogic);
  }

  /** метагейм слушает изменения данных во вью **/
  private subscribeMetaGame() {
    const sceneEvents = new SceneEvents(this);
    sceneEvents.on("savePlayerGold", (playerGold) => {
      metaGame.setPlayerGold(playerGold);
    });
    sceneEvents.on("saveLevelPlay", ({ levelId, isPlayerWin }) => {
      metaGame.saveLevelPlay({ levelId, isPlayerWin });
    });
  }
}
