import { ASSETS } from "../../assets";
import { gameObjectButton } from "../../components/ui";
import { services } from "../../serviceProvider";
import { SceneEvents, SoundEffect } from "../../SceneEvents";
import { MainAtlas } from "../../assets/atlases";

interface IProps {
  scene: Phaser.Scene;
}

export class UiMusicButton extends Phaser.GameObjects.Image {
  private unSubs?: (() => void)[];
  private readonly builder: MainAtlas;

  constructor(props: IProps) {
    const builder = ASSETS.images.builder(props.scene);
    super(props.scene, 0, 0, builder.atlas.pngUrl, builder.atlas.frames.button_music_off.filename);
    this.builder = builder;

    this.readSettings();
    this.subscribeToState();
    this.addInteraction();
  }

  subscribeToState() {
    const { scene } = this;
    const sceneEvents = new SceneEvents(scene);
    this.unSubs = [
      sceneEvents.on("musicSettingsOn", (isMusicOn) => {
        const frame = this.getFrame(isMusicOn);
        this.setFrame(frame);
      }),
    ];
  }

  private addInteraction() {
    const { scene } = this;
    const { soundMusicSettings } = services;
    const sceneEvents = new SceneEvents(scene);

    const onClick = () => {
      const isMusicOn = !soundMusicSettings.isMusicOn();
      sceneEvents.emit("musicSettingsOn", isMusicOn);
    };

    gameObjectButton({
      gameObject: this,
      inputTracker: this,
      onClick: () => {
        sceneEvents.emit("soundEffect", SoundEffect.click);
        onClick();
      },
      onOver: () => {
        sceneEvents.emit("soundEffect", SoundEffect.buttonHover);
      },
      options: {
        once: false,
        overMoveY: 4,
        clickMode: "up",
      },
    });
  }

  destroy(fromScene?: boolean) {
    super.destroy(fromScene);
    this.unSubs?.forEach((unSub) => unSub());
  }

  private getFrame(isMusicOn: boolean) {
    const { builder } = this;
    return isMusicOn ? builder.atlas.frames.button_music_on.filename : builder.atlas.frames.button_music_off.filename;
  }

  private readSettings() {
    const soundMusicSettings = services.soundMusicSettings;
    const isMusicOn = soundMusicSettings.isMusicOn();
    const frame = this.getFrame(isMusicOn);
    this.setFrame(frame);
  }
}
